import "C"

import (
	"errors"
	"fmt"
	"strings"
	"time"
	"unsafe"
)

// SQLiteDB wraps a sqlite3 connection.
type SQLiteDB struct {
	db *C.sqlite3
}

func sqliteErr(db *C.sqlite3, rc C.int) error {
	if db != nil {
		msg := C.GoString(C.sqlite3_errmsg(db))
		return errors.New(msg)
	}
	return fmt.Errorf("sqlite error %d", int(rc))
}

// OpenSQLite opens a database (":memory:" if dsn is empty).
func OpenSQLite(dsn string, allowExt bool) (*SQLiteDB, error) {
	if dsn == "" {
		dsn = ":memory:"
	}
	var db *C.sqlite3
	cs := C.CString(dsn)
	defer C.free(unsafe.Pointer(cs))
	rc := C.sqlite3_open_v2(cs, &db, C.SQLITE_OPEN_READWRITE|C.SQLITE_OPEN_CREATE|C.SQLITE_OPEN_URI, nil)
	if rc != C.SQLITE_OK {
		err := sqliteErr(db, rc)
		if db != nil {
			C.sqlite3_close_v2(db)
		}
		return nil, err
	}
	C.sqlite3_busy_timeout(db, 5000)
	C.register_functions(db)
	if allowExt {
		C.sqlite3_enable_load_extension(db, 1)
	}
	return &SQLiteDB{db: db}, nil
}

// Close closes the database.
func (d *SQLiteDB) Close() error {
	if d.db == nil {
		return nil
	}
	rc := C.sqlite3_close_v2(d.db)
	d.db = nil
	if rc != C.SQLITE_OK {
		return fmt.Errorf("sqlite close error %d", int(rc))
	}
	return nil
}

// SQLiteStmt is a prepared statement.
type SQLiteStmt struct {
	db   *C.sqlite3
	stmt *C.sqlite3_stmt
	tail string
}

// Prepare compiles a statement.
func (d *SQLiteDB) Prepare(query string) (*SQLiteStmt, error) {
	cs := C.CString(query)
	defer C.free(unsafe.Pointer(cs))
	var stmt *C.sqlite3_stmt
	var tail *C.char
	rc := C.sqlite3_prepare_v2(d.db, cs, -1, &stmt, &tail)
	if rc != C.SQLITE_OK {
		return nil, sqliteErr(d.db, rc)
	}
	t := ""
	if tail != nil {
		t = C.GoString(tail)
	}
	return &SQLiteStmt{db: d.db, stmt: stmt, tail: t}, nil
}

func (s *SQLiteStmt) bind(args []interface{}) error {
	C.sqlite3_reset(s.stmt)
	C.sqlite3_clear_bindings(s.stmt)
	for i, a := range args {
		idx := C.int(i + 1)
		var rc C.int
		switch v := a.(type) {
		case nil:
			rc = C.sqlite3_bind_null(s.stmt, idx)
		case string:
			if len(v) == 0 {
				rc = C.bind_text(s.stmt, idx, nil, 0)
				// sqlite treats NULL pointer as NULL; use empty static string instead
				empty := C.CString("")
				rc = C.bind_text(s.stmt, idx, empty, 0)
				C.free(unsafe.Pointer(empty))
			} else {
				b := []byte(v)
				rc = C.bind_text(s.stmt, idx, (*C.char)(unsafe.Pointer(&b[0])), C.int(len(b)))
			}
		case []byte:
			if len(v) == 0 {
				rc = C.sqlite3_bind_zeroblob(s.stmt, idx, 0)
			} else {
				rc = C.bind_blob(s.stmt, idx, unsafe.Pointer(&v[0]), C.int(len(v)))
			}
		case int:
			rc = C.sqlite3_bind_int64(s.stmt, idx, C.sqlite3_int64(v))
		case int64:
			rc = C.sqlite3_bind_int64(s.stmt, idx, C.sqlite3_int64(v))
		case float64:
			rc = C.sqlite3_bind_double(s.stmt, idx, C.double(v))
		case bool:
			if v {
				rc = C.sqlite3_bind_int64(s.stmt, idx, 1)
			} else {
				rc = C.sqlite3_bind_int64(s.stmt, idx, 0)
			}
		case time.Time:
			str := v.Format("2006-01-02 15:04:05.999999999-07:00")
			b := []byte(str)
			rc = C.bind_text(s.stmt, idx, (*C.char)(unsafe.Pointer(&b[0])), C.int(len(b)))
		default:
			str := fmt.Sprint(v)
			b := []byte(str)
			if len(b) == 0 {
				empty := C.CString("")
				rc = C.bind_text(s.stmt, idx, empty, 0)
				C.free(unsafe.Pointer(empty))
			} else {
				rc = C.bind_text(s.stmt, idx, (*C.char)(unsafe.Pointer(&b[0])), C.int(len(b)))
			}
		}
		if rc != C.SQLITE_OK {
			return sqliteErr(s.db, rc)
		}
	}
	return nil
}

// Exec runs the statement with args (no result rows).
func (s *SQLiteStmt) Exec(args ...interface{}) error {
	if err := s.bind(args); err != nil {
		return err
	}
	rc := C.sqlite3_step(s.stmt)
	for rc == C.SQLITE_ROW {
		rc = C.sqlite3_step(s.stmt)
	}
	if rc != C.SQLITE_DONE {
		err := sqliteErr(s.db, rc)
		C.sqlite3_reset(s.stmt)
		return err
	}
	C.sqlite3_reset(s.stmt)
	return nil
}

// Close finalizes the statement.
func (s *SQLiteStmt) Close() error {
	if s.stmt == nil {
		return nil
	}
	C.sqlite3_finalize(s.stmt)
	s.stmt = nil
	return nil
}

// Exec runs a statement without results.
func (d *SQLiteDB) Exec(query string, args ...interface{}) error {
	st, err := d.Prepare(query)
	if err != nil {
		return err
	}
	defer st.Close()
	return st.Exec(args...)
}

// SQLiteRows iterates over query results.
type SQLiteRows struct {
	stmt     *SQLiteStmt
	cols     []string
	decl     []string
	declLow  []string
	done     bool
	err      error
	started  bool
	firstRow bool
}

// Query executes a query and returns rows.
func (d *SQLiteDB) Query(query string, args ...interface{}) (*SQLiteRows, error) {
	st, err := d.Prepare(query)
	if err != nil {
		return nil, err
	}
	if err := st.bind(args); err != nil {
		st.Close()
		return nil, err
	}
	n := int(C.sqlite3_column_count(st.stmt))
	r := &SQLiteRows{stmt: st}
	r.cols = make([]string, n)
	r.decl = make([]string, n)
	r.declLow = make([]string, n)
	for i := 0; i < n; i++ {
		r.cols[i] = C.GoString(C.sqlite3_column_name(st.stmt, C.int(i)))
		dt := C.sqlite3_column_decltype(st.stmt, C.int(i))
		if dt != nil {
			r.decl[i] = C.GoString(dt)
			r.declLow[i] = strings.ToLower(r.decl[i])
		}
	}
	// Step once to surface runtime errors early (like database/sql does).
	rc := C.sqlite3_step(st.stmt)
	switch rc {
	case C.SQLITE_ROW:
		r.firstRow = true
	case C.SQLITE_DONE:
		r.done = true
	default:
		err := sqliteErr(d.db, rc)
		st.Close()
		return nil, err
	}
	return r, nil
}

// Columns returns column names.
func (r *SQLiteRows) Columns() []string { return r.cols }

// DeclTypes returns declared types.
func (r *SQLiteRows) DeclTypes() []string { return r.decl }

// Next advances to the next row.
func (r *SQLiteRows) Next() bool {
	if r.done {
		return false
	}
	if r.firstRow {
		r.firstRow = false
		return true
	}
	rc := C.sqlite3_step(r.stmt.stmt)
	switch rc {
	case C.SQLITE_ROW:
		return true
	case C.SQLITE_DONE:
		r.done = true
		return false
	default:
		r.err = sqliteErr(r.stmt.db, rc)
		r.done = true
		return false
	}
}

// Err returns the iteration error.
func (r *SQLiteRows) Err() error { return r.err }

