// Scan reads current row values converting like the go sqlite3 driver.
func (r *SQLiteRows) Scan() []interface{} {
	st := r.stmt.stmt
	n := len(r.cols)
	vals := make([]interface{}, n)
	for i := 0; i < n; i++ {
