		if configFile != "" {
			return cfg, fmt.Errorf("no file")
		}
		return cfg, nil
	}
	if c, ok := r.(io.Closer); ok {
		defer c.Close()
	}
	if err := json.NewDecoder(r).Decode(cfg); err != nil {
		return cfg, fmt.Errorf("config error: %w", err)
	}
	return cfg, nil
