	"PSV":   PSV,
	"WIDTH": WIDTH,
	"TEXT":  TEXT,
}

// guessExtension guesses the input format from the file name.
func guessExtension(tableName string) Format {
	dotExt := filepath.Ext(tableName)
	if dotExt == "" {
		debugf("Set in CSV because the extension is unknown: [%s]", tableName)
		return CSV
	}
	ext := strings.ToUpper(strings.TrimLeft(dotExt, "."))
	if f, ok := extToFormat[ext]; ok {
		return f
	}
	return guessExtension(strings.TrimSuffix(tableName, dotExt))
}

var outExtToFormat = map[string]Format{
	"CSV":   CSV,
	"LTSV":  LTSV,
	"JSON":  JSON,
	"JSONL": JSONL,
	"YAML":  YAML,
	"YML":   YAML,
	"TBLN":  TBLN,
	"RAW":   RAW,
	"MD":    MD,
	"AT":    AT,
	"VF":    VF,
}

// guessOutputFormat guesses output format from the file name.
func guessOutputFormat(fileName string) Format {
	name := fileName
	for {
		dotExt := filepath.Ext(name)
		if dotExt == "" {
