	OutHeader    bool
	OutNoWrap    bool
	OutNeedNULL  bool
	OutNULL      string
	OutStream    io.Writer
	ErrStream    io.Writer
}

// NewWriteOpts returns default write options.
func NewWriteOpts() *WriteOpts {
	return &WriteOpts{
		OutFormat:    CSV,
		OutDelimiter: ",",
		OutQuote:     "\"",
	}
}

// TRDSQL is the main structure.
type TRDSQL struct {
	Driver   string
	Dsn      string
	Importer *Importer
	Exporter *Exporter
}

// NewTRDSQL creates a TRDSQL.
func NewTRDSQL(im *Importer, ex *Exporter) *TRDSQL {
	return &TRDSQL{
		Driver:   "sqlite3",
		Dsn:      "",
		Importer: im,
		Exporter: ex,
	}
}

// DB is the database connection wrapper.
type DB struct {
	driver  string
	dsn     string
	sqlite  *SQLiteDB
	quote   string
	maxBulk int
}

// Connect opens a database.
func Connect(driver, dsn string) (*DB, error) {
	db := &DB{driver: driver, dsn: dsn, quote: "`", maxBulk: 1000}
	switch driver {
	case "sqlite3", "sqlite3_ext":
		s, err := OpenSQLite(dsn, driver == "sqlite3_ext")
		if err != nil {
			return nil, err
		}
		db.sqlite = s
	case "postgres":
		db.quote = `"`
		db.maxBulk = 65535
	case "mysql":
		db.quote = "`"
	default:
		return nil, fmt.Errorf("sql: unknown driver %q (forgotten import?)", driver)
	}
	return db, nil
}

// Begin starts a transaction.
func (db *DB) Begin() error {
	switch db.driver {
	case "postgres":
		return dialError(db.dsn, "postgres")
	case "mysql":
		return dialError(db.dsn, "mysql")
	}
	return db.sqlite.Exec("BEGIN")
}

// Commit commits.
func (db *DB) Commit() error {
	return db.sqlite.Exec("COMMIT")
}

// Close closes.
func (db *DB) Close() error {
	if db.sqlite != nil {
		return db.sqlite.Close()
	}
	return nil
}

// dialError emulates a connection attempt to an external database.
func dialError(dsn string, driver string) error {
	host := ""
	port := ""
	if driver == "postgres" {
		host, port = "localhost", "5432"
		for _, kv := range strings.Fields(dsn) {
			parts := strings.SplitN(kv, "=", 2)
			if len(parts) != 2 {
				continue
			}
			switch parts[0] {
			case "host":
				host = parts[1]
			case "port":
				port = parts[1]
			}
		}
	} else {
		host, port = "127.0.0.1", "3306"
		if i := strings.Index(dsn, "tcp("); i >= 0 {
			rest := dsn[i+4:]
			if j := strings.Index(rest, ")"); j >= 0 {
				addr := rest[:j]
				if h, p, err := net.SplitHostPort(addr); err == nil {
					host, port = h, p
				} else if addr != "" {
					host = addr
				}
			}
		}
	}
	conn, err := net.Dial("tcp", net.JoinHostPort(host, port))
	if err != nil {
		return err
	}
	conn.Close()
	return fmt.Errorf("pq: connection established but unsupported")
}

// Exec runs the SQL.
func (trd *TRDSQL) Exec(sqlQuery string) error {
	db, err := Connect(trd.Driver, trd.Dsn)
	if err != nil {
		return fmt.Errorf("connect: %w", err)
	}
	defer func() {
		db.Close()
	}()

	debugf("driver: %s, dsn: %s", trd.Driver, trd.Dsn)

	if err := db.Begin(); err != nil {
		return fmt.Errorf("begin: %w", err)
	}

	if trd.Importer != nil {
		sqlQuery, err = trd.Importer.Import(db, sqlQuery)
		if err != nil {
			return fmt.Errorf("import: %w", err)
		}
	}

	if trd.Exporter != nil {
		if err := trd.Exporter.Export(db, sqlQuery); err != nil {
			return fmt.Errorf("export: %w", err)
		}
	}

	if err := db.Commit(); err != nil {
		return fmt.Errorf("commit: %w", err)
	}
	return nil
}

// ErrNoStatement is returned for empty statements.
var ErrNoStatement = errors.New("no SQL statement")
EOF
echo ok"}

