package main

import (
	"strings"
)

// sqlFields splits SQL into tokens.
func sqlFields(query string) []string {
	parsed := []string{}
	buf := strings.Builder{}
	i := 0
	for i < len(query) {
		c := query[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == ',' || c == '(' || c == ')' || c == '=' || c == ';':
			if buf.Len() > 0 {
				parsed = append(parsed, buf.String())
				buf.Reset()
			}
			parsed = append(parsed, string(c))
			i++
		case c == '\'' || c == '"' || c == '`':
			j := i + 1
			for j < len(query) && query[j] != c {
				j++
			}
			if j < len(query) {
				j++
			}
			buf.WriteString(query[i:j])
			i = j
		default:
			buf.WriteByte(c)
			i++
		}
	}
	if buf.Len() > 0 {
		parsed = append(parsed, buf.String())
	}
	return parsed
}

func isSpaceToken(s string) bool {
	switch s {
	case " ", "\t", "\n", "\r":
		return true
	}
	return false
}

var fromTerminators = map[string]bool{
	"WHERE": true, "GROUP": true, "HAVING": true, "ORDER": true, "LIMIT": true,
	"OFFSET": true, "UNION": true, "WINDOW": true, "LEFT": true, "RIGHT": true,
	"FULL": true, "INNER": true, "CROSS": true, "FETCH": true, "FOR": true, "LATERAL": true,
}

// listTable returns table name candidates in the SQL tokens.
func listTable(tokens []string) []string {
	tables := []string{}
	expectTable := false
	inList := false
	for _, token := range tokens {
		if isSpaceToken(token) {
			continue
		}
		upper := strings.ToUpper(token)
		if upper == "FROM" || upper == "JOIN" || upper == "INTO" {
			expectTable = true
			inList = false
			continue
		}
		if expectTable {
			tables = append(tables, token)
			expectTable = false
			inList = true
			continue
		}
		if inList {
			if token == "," {
				expectTable = true
				continue
			}
			if fromTerminators[upper] {
				inList = false
			}
		}
	}
	return tables
}

// splitStatements splits tokens into statements at top-level ';' tokens.
func splitStatements(tokens []string) []string {
	stmts := []string{}
	buf := strings.Builder{}
	for _, token := range tokens {
		if token == ";" {
			stmts = append(stmts, buf.String())
			buf.Reset()
			continue
		}
		buf.WriteString(token)
	}
	stmts = append(stmts, buf.String())
	return stmts
}

// trimQuoteName removes quotes from a table name for file access.
func trimQuoteName(name string) string {
	return strings.Trim(name, "`\"")
}

// quotedName returns the table name to be used in SQL.
func quotedName(name string, quote string) string {
	if len(name) >= 2 && strings.HasPrefix(name, quote) && strings.HasSuffix(name, quote) {
		return name
	}
	return quote + name + quote
}
