// Import inserts the rows of the reader.
func (db *DB) Import(tableName string, names []string, reader Reader, opts *ReadOpts) error {
	columns := make([]string, len(names))
	for i := range names {
		columns[i] = db.quote + names[i] + db.quote
	}
	columnStr := strings.Join(columns, ", ")
	rowNum := 1
	preRead := reader.PreReadRow()
	if len(preRead) > 0 {
		rows := preRead
		if opts.InRowNumber {
			rows = make([][]interface{}, len(preRead))
			for i, r := range preRead {
				rows[i] = append([]interface{}{rowNum}, r...)
				rowNum++
			}
		}
		if err := db.insertRows(tableName, columnStr, len(names), rows); err != nil {
			return err
		}
