func (m *multiFileReader) Read(p []byte) (int, error) {
	for {
		if m.current == nil {
			if m.idx >= len(m.files) {
				return 0, io.EOF
			}
			name := m.files[m.idx]
			m.idx++
			debugf("Open: [%s]", name)
			rc, err := singleFileOpen(name)
			if err != nil {
				return 0, err
			}
