		m.current = nil
	}
	return nil
}

// NewReader creates a reader for the format.
func NewReader(reader io.Reader, opts *ReadOpts) (Reader, error) {
	if reader == nil {
		return nil, errors.New("nil reader")
	}
	switch opts.realFormat {
