	case TBLN:
		return NewTBLNReader(reader, opts)
	case WIDTH:
		return NewGWReader(reader, opts)
	case TEXT:
		return NewTextReader(reader, opts)
	default:
		return NewCSVReader(reader, opts)
	}
}
