package main

import (
	"encoding/csv"
	"fmt"
	"io"
	"log"
	"strconv"
)

// CSVReader reads CSV.
type CSVReader struct {
	reader    *csv.Reader
	names     []string
	types     []string
	preRead   [][]string
	inNULL    string
	needNULL  bool
	limitRead bool
}

// delimiter parses the delimiter string.
func delimiter(sepString string) (rune, error) {
	if sepString == "" {
		return 0, nil
	}
	sepRunes, err := strconv.Unquote(`'` + sepString + `'`)
	if err != nil {
		return ',', fmt.Errorf("can not get separator: %w:\"%s\"", err, sepString)
	}
	r := []rune(sepRunes)
	if len(r) == 0 {
		return 0, nil
	}
	return r[0], nil
}

// NewCSVReader creates a CSV reader.
func NewCSVReader(reader io.Reader, opts *ReadOpts) (*CSVReader, error) {
	r := &CSVReader{}
	r.reader = csv.NewReader(reader)
	r.reader.LazyQuotes = true
	r.reader.FieldsPerRecord = -1
	r.reader.TrimLeadingSpace = false
	d, err := delimiter(opts.InDelimiter)
	if err != nil {
		return nil, err
	}
	r.reader.Comma = d
	r.inNULL = opts.InNULL
	r.needNULL = opts.InNeedNULL

	preRead := opts.InPreRead
	if opts.InLimitRead > 0 {
		preRead = opts.InLimitRead + opts.InSkip
		r.limitRead = true
	}

	// Skip
	for i := 0; i < opts.InSkip; i++ {
		row, err := r.reader.Read()
		if err != nil {
			log.Printf("ERROR: skip error %s", err)
			break
		}
		first := ""
		if len(row) > 0 {
			first = row[0]
		}
		debugf("Skip row:[%s]", first)
	}

	// Header
	if opts.InHeader {
		row, err := r.reader.Read()
		if err != nil {
			if err == io.EOF {
				return nil, errNoRows
			}
			return nil, err
		}
		r.names = make([]string, len(row))
		for i, col := range row {
			if col == "" {
				r.names[i] = "c" + strconv.Itoa(i+1)
			} else {
				r.names[i] = col
			}
		}
	}

	// PreRead
	for n := 0; n < preRead; n++ {
		row, err := r.reader.Read()
		if err != nil {
			if err != io.EOF {
				return nil, err
			}
			break
		}
		rows := make([]string, len(row))
		for i, col := range row {
			rows[i] = col
			if len(r.names) < i+1 {
				r.names = append(r.names, "c"+strconv.Itoa(i+1))
			}
		}
		r.preRead = append(r.preRead, rows)
	}
	if len(r.names) == 0 {
		return nil, errNoRows
	}
	r.types = make([]string, len(r.names))
	for i := range r.types {
		r.types[i] = "text"
	}
	return r, nil
}

// Names returns column names.
func (r *CSVReader) Names() ([]string, error) {
	if len(r.names) == 0 {
		return nil, errNoRows
	}
	return r.names, nil
}

// Types returns column types.
func (r *CSVReader) Types() ([]string, error) {
	return r.types, nil
}

// PreReadRow returns pre-read rows.
func (r *CSVReader) PreReadRow() [][]interface{} {
	rows := make([][]interface{}, len(r.preRead))
	for n, row := range r.preRead {
		rows[n] = make([]interface{}, len(r.names))
		for i, col := range row {
			if i >= len(r.names) {
				break
			}
			rows[n][i] = r.convert(col)
		}
	}
	return rows
}

func (r *CSVReader) convert(col string) interface{} {
	if r.needNULL && col == r.inNULL {
		return nil
	}
	return col
}

// ReadRow reads the next row.
func (r *CSVReader) ReadRow(row []interface{}) ([]interface{}, error) {
	if r.limitRead {
		return nil, io.EOF
	}
	record, err := r.reader.Read()
	if err != nil {
		return row, err
	}
	for i := range row {
		if i < len(record) {
			row[i] = r.convert(record[i])
		} else {
			row[i] = nil
		}
	}
	return row, nil
}
EOF
echo ok"}

