	preRead   []map[string]interface{}
	names     []string
	types     []string
	query     jqQuery
	queryStr  string
	inNULL    string
	needNULL  bool
	limitRead bool
	pending   [][]interface{}
}

// NewJSONReader creates a JSON reader.
func NewJSONReader(reader io.Reader, opts *ReadOpts) (*JSONReader, error) {
	r := &JSONReader{}
	r.reader = json.NewDecoder(reader)
	r.reader.UseNumber()
	r.inNULL = opts.InNULL
	r.needNULL = opts.InNeedNULL

	if opts.InJQuery != "" {
		q, err := compileJQ(opts.InJQuery)
		if err != nil {
			return nil, fmt.Errorf("%w gojq:(%s) ", err, opts.InJQuery)
		}
		r.query = q
		r.queryStr = opts.InJQuery
	}

	preRead := opts.InPreRead
	if opts.InLimitRead > 0 {
		preRead = opts.InLimitRead + opts.InSkip
		r.limitRead = true
	}

	var top interface{}
	for i := 0; i < preRead; i++ {
		top = nil
		if err := r.reader.Decode(&top); err != nil {
			if err != io.EOF {
				return r, fmt.Errorf("%w: %s", errInvalidJSON, err)
			}
			debugf("%s", err.Error())
			break
		}
		if r.query != nil {
			if err := r.jqPreRead(top); err != nil {
				return r, err
			}
			continue
		}
		r.readAhead(top)
	}
	r.types = make([]string, len(r.names))
	for i := range r.types {
		r.types[i] = "text"
	}
	return r, nil
}

func (r *JSONReader) jqPreRead(top interface{}) error {
	outs, err := r.query.Run(top)
	if err != nil {
		return fmt.Errorf("%w gojq:(%s) ", err, r.queryStr)
	}
	for _, v := range outs {
		r.readAhead(v)
	}
	return nil
}

func (r *JSONReader) readAhead(top interface{}) {
	switch m := top.(type) {
	case []interface{}:
		r.preRead = make([]map[string]interface{}, 0, len(m))
		if r.reader.More() {
			// JSONL: the array is a single value
			r.preRead = append(r.preRead, r.etcRow(m))
			return
		}
		for _, v := range m {
			switch mm := v.(type) {
			case map[string]interface{}:
				r.preRead = append(r.preRead, r.objectRow(mm))
			default:
				r.preRead = append(r.preRead, r.etcRow(mm))
			}
		}
	case map[string]interface{}:
		r.preRead = append(r.preRead, r.objectRow(m))
	default:
		r.preRead = append(r.preRead, r.etcRow(m))
	}
}

func (r *JSONReader) addName(name string) {
	for _, n := range r.names {
		if n == name {
			return
		}
	}
	r.names = append(r.names, name)
}

func (r *JSONReader) objectRow(obj map[string]interface{}) map[string]interface{} {
	row := make(map[string]interface{}, len(obj))
	for k, v := range obj {
		r.addName(k)
		row[k] = r.jsonString(v)
	}
	return row
}

func (r *JSONReader) etcRow(val interface{}) map[string]interface{} {
	r.addName("c1")
	row := make(map[string]interface{}, 1)
	row["c1"] = r.jsonString(val)
	return row
}

func (r *JSONReader) jsonString(val interface{}) interface{} {
	var str string
	switch t := val.(type) {
	case nil:
		return nil
	case map[string]interface{}, []interface{}:
		b, err := json.Marshal(t)
		if err != nil {
			debugf("ERROR: jsonString:%s", err)
		}
		str = string(b)
	case json.Number:
		str = t.String()
	case string:
		str = t
	default:
		str = fmt.Sprint(t)
	}
	if r.needNULL && str == r.inNULL {
		return nil
	}
	return str
}

