func (r *JSONReader) Names() ([]string, error) {
	if len(r.names) == 0 {
		return nil, errInvalidNames
	}
	return r.names, nil
}

// Types returns column types.
func (r *JSONReader) Types() ([]string, error) {
	return r.types, nil
}

// PreReadRow returns pre-read rows.
func (r *JSONReader) PreReadRow() [][]interface{} {
	rows := make([][]interface{}, len(r.preRead))
	for n, m := range r.preRead {
		rows[n] = make([]interface{}, len(r.names))
		for i, name := range r.names {
			rows[n][i] = m[name]
		}
	}
	return rows
}

// ReadRow reads the next row.
func (r *JSONReader) ReadRow(row []interface{}) ([]interface{}, error) {
	if r.limitRead {
		return nil, io.EOF
	}
	if len(r.pending) > 0 {
		p := r.pending[0]
		r.pending = r.pending[1:]
		copy(row, p)
		return row, nil
	}
	var top interface{}
	if err := r.reader.Decode(&top); err != nil {
		return nil, err
	}
	if r.query != nil {
		outs, err := r.query.Run(top)
		if err != nil {
			return nil, fmt.Errorf("%w gojq:(%s) ", err, r.queryStr)
		}
		if len(outs) == 0 {
			return r.ReadRow(row)
		}
		for i, v := range outs {
			rr := make([]interface{}, len(row))
			r.rowParse(rr, v)
			if i == 0 {
				copy(row, rr)
			} else {
				r.pending = append(r.pending, rr)
			}
		}
		return row, nil
	}
	r.rowParse(row, top)
	return row, nil
}

func (r *JSONReader) rowParse(row []interface{}, top interface{}) {
	switch m := top.(type) {
	case map[string]interface{}:
		for i, name := range r.names {
			if v, ok := m[name]; ok {
				row[i] = r.jsonString(v)
			} else {
				row[i] = nil
			}
		}
	default:
		for i := range row {
			row[i] = nil
		}
		if len(row) > 0 {
			row[0] = r.jsonString(top)
		}
	}
}

// jsonIsObjectOrArray reports whether a string looks like JSON object/array.
func jsonIsObjectOrArray(s string) bool {
	return len(s) > 0 && (s[0] == '{' || s[0] == '[') && strings.TrimSpace(s) != ""
}
