package main

import (
	"bufio"
	"fmt"
	"io"
	"regexp"
	"strconv"
	"strings"
)

// TBLNReader reads TBLN.
type TBLNReader struct {
	reader    *bufio.Reader
	names     []string
	types     []string
	preRead   [][]string
	inNULL    string
	needNULL  bool
	limitRead bool
	fixed     bool
	extras    map[string]string
}

var tblnEscRep = regexp.MustCompile(`\|(\|+)`)

// NewTBLNReader creates a TBLN reader.
func NewTBLNReader(reader io.Reader, opts *ReadOpts) (*TBLNReader, error) {
	r := &TBLNReader{}
	r.reader = bufio.NewReader(reader)
	r.inNULL = opts.InNULL
	r.needNULL = opts.InNeedNULL
	r.extras = map[string]string{}

	preRead := opts.InPreRead
	if opts.InLimitRead > 0 {
		preRead = opts.InLimitRead + opts.InSkip
		r.limitRead = true
	}

	for i := 0; i < opts.InSkip; i++ {
		_, err := r.readRow()
		if err != nil {
			debugf("ERROR: skip error %s", err)
			break
		}
	}

	for i := 0; i < preRead; i++ {
		row, err := r.readRow()
		if err != nil {
			if err != io.EOF {
				return r, err
			}
			break
		}
		r.preRead = append(r.preRead, row)
	}
	return r, nil
}

// readRow reads the next data row (handling extras/comments).
func (r *TBLNReader) readRow() ([]string, error) {
	for {
		line, err := r.reader.ReadString('\n')
		if err != nil {
			if err == io.EOF && len(line) > 0 {
				// process last line without newline
			} else {
				return nil, err
			}
		}
		line = strings.TrimRight(line, "\r\n")
		if line == "" {
			if err == io.EOF {
				return nil, io.EOF
			}
			continue
		}
		switch {
		case strings.HasPrefix(line, "# "), line == "#":
			if err == io.EOF {
				return nil, io.EOF
			}
			continue
		case strings.HasPrefix(line, "#"):
			if err == io.EOF {
				return nil, io.EOF
			}
			continue
		case strings.HasPrefix(line, "; "):
			if e := r.parseExtra(line[2:]); e != nil {
				return nil, e
			}
			if err == io.EOF {
				return nil, io.EOF
			}
			continue
		case strings.HasPrefix(line, "| ") && strings.HasSuffix(line, " |"):
			row := tblnSplitRow(line)
			if !r.fixed {
				r.fix(len(row))
			}
			if len(r.names) != len(row) {
				return nil, fmt.Errorf("invalid column num (%d!=%d) %v", len(r.names), len(row), row)
			}
			return row, nil
		default:
			return nil, fmt.Errorf("unsupported line (%s)", line)
		}
	}
}

func (r *TBLNReader) fix(n int) {
	if len(r.names) == 0 {
		r.names = make([]string, n)
		for i := range r.names {
			r.names[i] = "c" + strconv.Itoa(i+1)
		}
	}
	if len(r.types) == 0 {
		r.types = make([]string, len(r.names))
		for i := range r.types {
			r.types[i] = "text"
		}
	}
	r.fixed = true
}

func (r *TBLNReader) parseExtra(s string) error {
	kv := strings.SplitN(s, ": ", 2)
	if len(kv) != 2 {
		kv = strings.SplitN(s, ":", 2)
		if len(kv) != 2 {
			return fmt.Errorf("unsupported line (; %s)", s)
		}
	}
	key := kv[0]
	val := kv[1]
	if r.fixed {
		r.extras[key] = val
		return nil
	}
	switch key {
	case "name":
		if strings.HasPrefix(val, "| ") && strings.HasSuffix(val, " |") {
			r.names = tblnSplitRow(val)
		}
	case "type":
		if strings.HasPrefix(val, "| ") && strings.HasSuffix(val, " |") {
			r.types = tblnSplitRow(val)
		}
	default:
		r.extras[key] = val
	}
	return nil
}

func tblnSplitRow(line string) []string {
	body := line[2 : len(line)-2]
	parts := strings.Split(body, " | ")
	for i, p := range parts {
		parts[i] = tblnEscRep.ReplaceAllString(p, "$1")
	}
	return parts
}

// Names returns column names.
func (r *TBLNReader) Names() ([]string, error) {
	if len(r.names) == 0 {
		return nil, errInvalidNames
	}
	return r.names, nil
}

// Types returns column types.
func (r *TBLNReader) Types() ([]string, error) {
	if len(r.types) == 0 {
		r.types = make([]string, len(r.names))
		for i := range r.types {
			r.types[i] = "text"
		}
	}
	return r.types, nil
}

func (r *TBLNReader) convert(s string) interface{} {
	if r.needNULL && s == r.inNULL {
		return nil
	}
	return s
}

// PreReadRow returns pre-read rows.
func (r *TBLNReader) PreReadRow() [][]interface{} {
	rows := make([][]interface{}, len(r.preRead))
	for n, row := range r.preRead {
		rows[n] = make([]interface{}, len(row))
		for i, c := range row {
			rows[n][i] = r.convert(c)
		}
	}
	return rows
}

// ReadRow reads the next row.
func (r *TBLNReader) ReadRow(row []interface{}) ([]interface{}, error) {
	if r.limitRead {
		return nil, io.EOF
	}
	rec, err := r.readRow()
	if err != nil {
		return row, err
	}
	for i := range row {
		if i < len(rec) {
			row[i] = r.convert(rec[i])
		} else {
			row[i] = nil
		}
	}
	return row, nil
}
