package main

import (
	"bufio"
	"strings"
	"unicode"
	"unicode/utf8"
)

// CSVWriter writes CSV.
type CSVWriter struct {
	writer    *bufio.Writer
	outNULL   string
	needNULL  bool
	outHeader bool
	allQuotes bool
	useCRLF   bool
	delimiter rune
	quote     rune
}

// NewCSVWriter creates a CSV writer.
func NewCSVWriter(opts *WriteOpts) *CSVWriter {
	w := &CSVWriter{}
	w.writer = newBufWriter(opts.OutStream)
	d, err := delimiter(opts.OutDelimiter)
	if err != nil {
		debugf("%s", err)
	}
	w.delimiter = d
	w.quote = 0
	if r := []rune(opts.OutQuote); len(r) > 0 {
		w.quote = r[0]
	}
	w.allQuotes = opts.OutAllQuotes
	w.useCRLF = opts.OutUseCRLF
	w.outHeader = opts.OutHeader
	w.outNULL = opts.OutNULL
	w.needNULL = opts.OutNeedNULL
	return w
}

// PreWrite writes the header.
func (w *CSVWriter) PreWrite(columns []string, types []string) error {
	if w.outHeader {
		return w.writeRecord(columns, nil)
	}
	return nil
}

// WriteRow writes a row.
func (w *CSVWriter) WriteRow(values []interface{}, columns []string) error {
	fields := make([]string, len(values))
	isNull := make([]bool, len(values))
	for i, v := range values {
		if v == nil {
			isNull[i] = true
			if w.needNULL {
				fields[i] = w.outNULL
			} else {
				fields[i] = ""
			}
			continue
		}
		fields[i] = ValString(v)
	}
	return w.writeRecord(fields, isNull)
}

func (w *CSVWriter) fieldNeedsQuotes(field string) bool {
	if field == "" {
		return false
	}
	if w.delimiter != 0 && strings.ContainsRune(field, w.delimiter) {
		return true
	}
	if w.quote != 0 && strings.ContainsRune(field, w.quote) {
		return true
	}
	if strings.ContainsAny(field, "\r\n") {
		return true
	}
	r1, _ := utf8.DecodeRuneInString(field)
	return unicode.IsSpace(r1)
}

func (w *CSVWriter) writeRecord(fields []string, isNull []bool) error {
	for i, field := range fields {
		if i > 0 {
			if _, err := w.writer.WriteRune(w.delimiter); err != nil {
				return err
			}
		}
		if isNull != nil && isNull[i] {
			if _, err := w.writer.WriteString(field); err != nil {
				return err
			}
			continue
		}
		if !w.allQuotes && !w.fieldNeedsQuotes(field) {
			if _, err := w.writer.WriteString(field); err != nil {
				return err
			}
			continue
		}
		if _, err := w.writer.WriteRune(w.quote); err != nil {
			return err
		}
		for _, r := range field {
			if r == w.quote {
				w.writer.WriteRune(w.quote)
			}
			w.writer.WriteRune(r)
		}
		if _, err := w.writer.WriteRune(w.quote); err != nil {
			return err
		}
	}
	var err error
	if w.useCRLF {
		_, err = w.writer.WriteString("\r\n")
	} else {
		err = w.writer.WriteByte('\n')
	}
	return err
}

// PostWrite flushes.
func (w *CSVWriter) PostWrite() error {
	return w.writer.Flush()
}

// RAWWriter writes raw delimited text.
type RAWWriter struct {
	writer    *bufio.Writer
	outNULL   string
	needNULL  bool
	outHeader bool
	delimiter string
}

// NewRAWWriter creates a RAW writer.
func NewRAWWriter(opts *WriteOpts) *RAWWriter {
	w := &RAWWriter{}
	w.writer = newBufWriter(opts.OutStream)
	d, err := delimiter(opts.OutDelimiter)
	if err != nil {
		debugf("%s", err)
	}
	w.delimiter = string(d)
	w.outHeader = opts.OutHeader
	w.outNULL = opts.OutNULL
	w.needNULL = opts.OutNeedNULL
	return w
}

// PreWrite writes the header.
func (w *RAWWriter) PreWrite(columns []string, types []string) error {
	if w.outHeader {
		_, err := w.writer.WriteString(strings.Join(columns, w.delimiter) + "\n")
		return err
	}
	return nil
}

// WriteRow writes a row.
func (w *RAWWriter) WriteRow(values []interface{}, columns []string) error {
	for i, v := range values {
		if i > 0 {
			w.writer.WriteString(w.delimiter)
		}
		if v == nil && w.needNULL {
			w.writer.WriteString(w.outNULL)
			continue
		}
		w.writer.WriteString(ValString(v))
	}
	_, err := w.writer.WriteString("\n")
	return err
}

// PostWrite flushes.
func (w *RAWWriter) PostWrite() error {
	return w.writer.Flush()
}

// LTSVWriter writes LTSV.
type LTSVWriter struct {
	writer   *bufio.Writer
	outNULL  string
	needNULL bool
}

// NewLTSVWriter creates an LTSV writer.
func NewLTSVWriter(opts *WriteOpts) *LTSVWriter {
	w := &LTSVWriter{}
	w.writer = newBufWriter(opts.OutStream)
	w.outNULL = opts.OutNULL
	w.needNULL = opts.OutNeedNULL
	return w
}

// PreWrite does nothing.
func (w *LTSVWriter) PreWrite(columns []string, types []string) error {
	return nil
}

// WriteRow writes a row.
func (w *LTSVWriter) WriteRow(values []interface{}, columns []string) error {
	for i, v := range values {
		if i > 0 {
			w.writer.WriteString("\t")
		}
		w.writer.WriteString(columns[i])
		w.writer.WriteString(":")
		if v == nil && w.needNULL {
			w.writer.WriteString(w.outNULL)
			continue
		}
		w.writer.WriteString(ValString(v))
	}
	_, err := w.writer.WriteString("\n")
	return err
}

// PostWrite flushes.
func (w *LTSVWriter) PostWrite() error {
	return w.writer.Flush()
}
