cat > writer_json.go <<'EOF'
package main

import (
	"bufio"
	"bytes"
	"encoding/json"
	"time"
	"unicode/utf8"
	"encoding/hex"
)

type keyValue struct {
	key string
	val []byte // marshaled JSON
}

// orderedRow keeps JSON key order with map semantics.
type orderedRow struct {
	keys []string
	vals map[string][]byte
}

func newOrderedRow() *orderedRow {
	return &orderedRow{vals: map[string][]byte{}}
}

func (o *orderedRow) set(k string, v []byte) {
	if _, ok := o.vals[k]; !ok {
		o.keys = append(o.keys, k)
	}
	o.vals[k] = v
}

func (o *orderedRow) marshal(buf *bytes.Buffer) {
	buf.WriteByte('{')
	for i, k := range o.keys {
		if i > 0 {
			buf.WriteByte(',')
		}
		kb, _ := json.Marshal(k)
		buf.Write(kb)
		buf.WriteByte(':')
		buf.Write(o.vals[k])
	}
	buf.WriteByte('}')
}

// jsonValue converts a value to marshaled JSON.
func jsonValue(v interface{}, needNULL bool, outNULL string) []byte {
	switch t := v.(type) {
	case nil:
		if needNULL {
			b, _ := json.Marshal(outNULL)
			return b
		}
		return []byte("null")
	case string:
		return jsonStringValue(t)
	case []byte:
		if utf8.Valid(t) {
			return jsonStringValue(string(t))
		}
		b, _ := json.Marshal(`\x` + hex.EncodeToString(t))
		return b
	case time.Time:
		b, _ := json.Marshal(t)
		return b
	default:
		b, err := json.Marshal(t)
		if err != nil {
			b, _ = json.Marshal(ValString(t))
		}
		return b
	}
}

func jsonStringValue(s string) []byte {
	if len(s) > 0 && (s[0] == '{' || s[0] == '[') && json.Valid([]byte(s)) {
		var buf bytes.Buffer
		if err := json.Compact(&buf, []byte(s)); err == nil {
			// Apply HTML escaping like encoding/json does for RawMessage.
			var out bytes.Buffer
			json.HTMLEscape(&out, buf.Bytes())
			return out.Bytes()
		}
	}
	b, _ := json.Marshal(s)
	return b
}

// JSONWriter writes a JSON array.
type JSONWriter struct {
	writer   *bufio.Writer
	outNULL  string
	needNULL bool
	rows     []*orderedRow
}

// NewJSONWriter creates a JSON writer.
func NewJSONWriter(opts *WriteOpts) *JSONWriter {
	w := &JSONWriter{}
	w.writer = newBufWriter(opts.OutStream)
	w.outNULL = opts.OutNULL
	w.needNULL = opts.OutNeedNULL
	return w
}

// PreWrite initializes.
func (w *JSONWriter) PreWrite(columns []string, types []string) error {
	w.rows = []*orderedRow{}
	return nil
}

// WriteRow collects a row.
func (w *JSONWriter) WriteRow(values []interface{}, columns []string) error {
	row := newOrderedRow()
	for i, col := range values {
		row.set(columns[i], jsonValue(col, w.needNULL, w.outNULL))
	}
	w.rows = append(w.rows, row)
	return nil
}

// PostWrite writes the collected rows.
func (w *JSONWriter) PostWrite() error {
	var buf bytes.Buffer
	buf.WriteByte('[')
	for i, r := range w.rows {
		if i > 0 {
			buf.WriteByte(',')
		}
		r.marshal(&buf)
