package main

import (
	"fmt"
	"io"
	"math"
	"regexp"
	"strings"

	"github.com/mattn/go-runewidth"
)

// Minimal clone of the classic ASCII table writer behaviour.

const twMaxRowWidth = 30

var (
	twDecimal = regexp.MustCompile(`^-?(?:\d{1,3}(?:,\d{3})*|\d+)(?:\.\d+)?$`)
	twPercent = regexp.MustCompile(`^-?\d+\.?\d*$%$`)
	twAnsi    = regexp.MustCompile("\033\\[(?:[0-9]{1,3}(?:;[0-9]{1,3})*)?[m|K]")
)

type twBorder struct {
	Left, Right, Top, Bottom bool
}

type twTable struct {
	out      io.Writer
	lines    [][][]string
	cs       map[int]int
	rs       map[int]int
	headers  [][]string
	autoWrap bool
	reflow   bool
	mW       int
	pCenter  string
	pRow     string
	pColumn  string
	hdrLine  bool
	borders  twBorder
}

func newTwTable(w io.Writer) *twTable {
	return &twTable{
		out:      w,
		lines:    [][][]string{},
		cs:       map[int]int{},
		rs:       map[int]int{},
		headers:  [][]string{},
		autoWrap: true,
		reflow:   true,
		mW:       twMaxRowWidth,
		pCenter:  "+",
		pRow:     "-",
		pColumn:  "|",
		hdrLine:  true,
		borders:  twBorder{Left: true, Right: true, Top: true, Bottom: true},
	}
}

func twDisplayWidth(s string) int {
	return runewidth.StringWidth(twAnsi.ReplaceAllLiteralString(s, ""))
}

func twPad(s, pad string, width int) string {
	gap := width - twDisplayWidth(s)
	if gap > 0 {
		gapLeft := int(math.Ceil(float64(gap / 2)))
		gapRight := gap - gapLeft
		return strings.Repeat(pad, gapLeft) + s + strings.Repeat(pad, gapRight)
	}
	return s
}

func twPadRight(s, pad string, width int) string {
	gap := width - twDisplayWidth(s)
	if gap > 0 {
		return s + strings.Repeat(pad, gap)
	}
	return s
}

func twPadLeft(s, pad string, width int) string {
	gap := width - twDisplayWidth(s)
	if gap > 0 {
		return strings.Repeat(pad, gap) + s
	}
	return s
}

func twWrapString(s string, lim int) ([]string, int) {
	words := strings.Split(strings.Replace(s, "\n", " ", -1), " ")
	var lines []string
	max := 0
	for _, v := range words {
		max = runewidth.StringWidth(v)
		if max > lim {
			lim = max
		}
	}
	for _, line := range twWrapWords(words, 1, lim, 1e5) {
		lines = append(lines, strings.Join(line, " "))
	}
	return lines, lim
}

func twWrapWords(words []string, spc, lim, pen int) [][]string {
	n := len(words)
	length := make([][]int, n)
	for i := 0; i < n; i++ {
		length[i] = make([]int, n)
		length[i][i] = runewidth.StringWidth(words[i])
		for j := i + 1; j < n; j++ {
			length[i][j] = length[i][j-1] + spc + runewidth.StringWidth(words[j])
		}
	}
	nbrk := make([]int, n)
	cost := make([]int, n)
	for i := range cost {
		cost[i] = math.MaxInt32
	}
	for i := n - 1; i >= 0; i-- {
		if length[i][n-1] <= lim {
			cost[i] = 0
			nbrk[i] = n
		} else {
			for j := i + 1; j < n; j++ {
				d := lim - length[i][j-1]
				c := d*d + cost[j]
				if length[i][j-1] > lim {
					c += pen
				}
				if c < cost[i] {
					cost[i] = c
					nbrk[i] = j
				}
			}
		}
	}
	var lines [][]string
	i := 0
	for i < n {
		lines = append(lines, words[i:nbrk[i]])
		i = nbrk[i]
	}
	return lines
}

func (t *twTable) parseDimension(str string, colKey, rowKey int) []string {
	raw := strings.Split(str, "\n")
	maxWidth := 0
	for _, line := range raw {
		if w := twDisplayWidth(line); w > maxWidth {
			maxWidth = w
		}
	}
	if t.autoWrap {
		if maxWidth > t.mW {
			maxWidth = t.mW
		}
		newMaxWidth := maxWidth
		newRaw := make([]string, 0, len(raw))
		if t.reflow {
			raw = []string{strings.Join(raw, " ")}
		}
		for i, para := range raw {
			paraLines, _ := twWrapString(para, maxWidth)
			for _, line := range paraLines {
				if w := twDisplayWidth(line); w > newMaxWidth {
					newMaxWidth = w
				}
			}
			if i > 0 {
				newRaw = append(newRaw, " ")
			}
			newRaw = append(newRaw, paraLines...)
		}
		raw = newRaw
		maxWidth = newMaxWidth
	}
	v, ok := t.cs[colKey]
	if !ok || v < maxWidth || v == 0 {
		t.cs[colKey] = maxWidth
	}
	h := len(raw)
	v, ok = t.rs[rowKey]
	if !ok || v < h || v == 0 {
		t.rs[rowKey] = h
	}
	return raw
}

func (t *twTable) SetHeader(keys []string) {
	for i, v := range keys {
		lines := t.parseDimension(v, i, -1)
		t.headers = append(t.headers, lines)
	}
}

func (t *twTable) Append(row []string) {
	n := len(t.lines)
	line := [][]string{}
	for i, v := range row {
		out := t.parseDimension(v, i, n)
		line = append(line, out)
	}
	t.lines = append(t.lines, line)
}

func (t *twTable) printLine(nl bool) {
	fmt.Fprint(t.out, t.pCenter)
	for i := 0; i < len(t.cs); i++ {
		v := t.cs[i]
		fmt.Fprintf(t.out, "%s%s%s%s", t.pRow, strings.Repeat(t.pRow, v), t.pRow, t.pCenter)
	}
	if nl {
		fmt.Fprint(t.out, "\n")
	}
}

func twCond(cond bool, valid, inValid string) string {
	if cond {
		return valid
	}
	return inValid
}

func (t *twTable) printHeading() {
	if len(t.headers) < 1 {
		return
	}
	end := len(t.cs) - 1
	max := t.rs[-1]
	for x := 0; x < max; x++ {
		fmt.Fprint(t.out, twCond(t.borders.Left, t.pColumn, " "))
		for y := 0; y <= end; y++ {
			v := t.cs[y]
			h := ""
			if y < len(t.headers) && x < len(t.headers[y]) {
				h = t.headers[y][x]
			}
			pad := twCond((y == end && !t.borders.Left), " ", t.pColumn)
			fmt.Fprintf(t.out, " %s %s", twPad(h, " ", v), pad)
		}
		fmt.Fprint(t.out, "\n")
	}
	if t.hdrLine {
		t.printLine(true)
	}
}

func (t *twTable) printRow(columns [][]string, rowIdx int) {
	max := t.rs[rowIdx]
	total := len(columns)
	for i, line := range columns {
		length := len(line)
		pad := max - length
		for n := 0; n < pad; n++ {
			columns[i] = append(columns[i], "  ")
		}
	}
	for x := 0; x < max; x++ {
		for y := 0; y < total; y++ {
			fmt.Fprint(t.out, twCond((!t.borders.Left && y == 0), " ", t.pColumn))
			fmt.Fprint(t.out, " ")
			str := columns[y][x]
			if twDecimal.MatchString(strings.TrimSpace(str)) || twPercent.MatchString(strings.TrimSpace(str)) {
				fmt.Fprint(t.out, twPadLeft(str, " ", t.cs[y]))
			} else {
				fmt.Fprint(t.out, twPadRight(str, " ", t.cs[y]))
			}
			fmt.Fprint(t.out, " ")
		}
		fmt.Fprint(t.out, twCond(t.borders.Left, t.pColumn, " "))
		fmt.Fprint(t.out, "\n")
	}
}

func (t *twTable) Render() {
	if t.borders.Top {
		t.printLine(true)
	}
	t.printHeading()
	for i, lines := range t.lines {
		t.printRow(lines, i)
	}
	if t.borders.Bottom {
		t.printLine(true)
	}
}

// TWWriter writes ASCII table / markdown.
type TWWriter struct {
	writer   *twTable
	out      io.Writer
	outNULL  string
	needNULL bool
	markdown bool
	noWrap   bool
	results  []string
	bw       interface{ Flush() error }
}

// NewTWWriter creates an AT/MD writer.
func NewTWWriter(opts *WriteOpts, markdown bool) *TWWriter {
	w := &TWWriter{}
	bw := newBufWriter(opts.OutStream)
	w.bw = bw
	w.out = bw
	w.outNULL = opts.OutNULL
	w.needNULL = opts.OutNeedNULL
	w.markdown = markdown
	w.noWrap = opts.OutNoWrap
	return w
}

// PreWrite sets up the table.
func (w *TWWriter) PreWrite(columns []string, types []string) error {
	w.writer = newTwTable(w.out)
	if w.noWrap {
		w.writer.autoWrap = false
	}
	if w.markdown {
		w.writer.borders = twBorder{Left: true, Top: false, Right: true, Bottom: false}
		w.writer.pCenter = "|"
	}
	w.writer.SetHeader(columns)
	w.results = make([]string, len(columns))
	return nil
}

// WriteRow appends a row.
func (w *TWWriter) WriteRow(values []interface{}, columns []string) error {
	for i, col := range values {
		str := ""
		if col == nil && w.needNULL {
			str = w.outNULL
		} else {
			str = ValString(col)
		}
		if w.markdown {
			str = strings.ReplaceAll(str, "|", `\|`)
		}
		w.results[i] = str
	}
	w.writer.Append(w.results)
	return nil
}

// PostWrite renders.
func (w *TWWriter) PostWrite() error {
	w.writer.Render()
	return w.bw.Flush()
}
