)

type twBorder struct {
	Left, Right, Top, Bottom bool
}

type twTable struct {
	out      io.Writer
	lines    [][][]string
	cs       map[int]int
	rs       map[int]int
	headers  [][]string
	autoWrap bool
	reflow   bool
	mW       int
	pCenter  string
