package main

import (
	"bytes"
	"fmt"
	"math"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"

	"gopkg.in/yaml.v3"
)

// yamlMap is an ordered mapping.
type yamlMap struct {
	keys   []string
	values []interface{}
}

func (m *yamlMap) add(k string, v interface{}) {
	m.keys = append(m.keys, k)
	m.values = append(m.values, v)
}

func (m *yamlMap) get(k string) (interface{}, bool) {
	for i := len(m.keys) - 1; i >= 0; i-- {
		if m.keys[i] == k {
			return m.values[i], true
		}
	}
	return nil, false
}

// yamlDecoder decodes YAML documents.
type yamlDecoder struct {
	dec *yaml.Decoder
}

func newYAMLDecoder(b []byte) *yamlDecoder {
	return &yamlDecoder{dec: yaml.NewDecoder(bytes.NewReader(b))}
}

// next decodes the next document. Returns io.EOF at end.
func (d *yamlDecoder) next() (interface{}, error) {
	var node yaml.Node
	if err := d.dec.Decode(&node); err != nil {
		return nil, err
	}
	return nodeToValue(&node), nil
}

func nodeToValue(n *yaml.Node) interface{} {
	switch n.Kind {
	case yaml.DocumentNode:
		if len(n.Content) == 0 {
			return nil
		}
		return nodeToValue(n.Content[0])
	case yaml.MappingNode:
		m := &yamlMap{}
		for i := 0; i+1 < len(n.Content); i += 2 {
			k := nodeToValue(n.Content[i])
			m.add(yamlKeyString(k), nodeToValue(n.Content[i+1]))
		}
		return m
	case yaml.SequenceNode:
		seq := make([]interface{}, 0, len(n.Content))
		for _, c := range n.Content {
			seq = append(seq, nodeToValue(c))
		}
		return seq
	case yaml.ScalarNode:
		if n.Style == yaml.DoubleQuotedStyle || n.Style == yaml.SingleQuotedStyle ||
			n.Style == yaml.LiteralStyle || n.Style == yaml.FoldedStyle {
			return n.Value
		}
		if n.Tag == "!!str" && n.Style == 0 && n.ShortTag() == "!!str" && strings.HasPrefix(n.Tag, "!!") && n.Tag != "" && isExplicitStrTag(n) {
			return n.Value
		}
		return resolvePlainScalar(n.Value)
	case yaml.AliasNode:
		if n.Alias != nil {
			return nodeToValue(n.Alias)
		}
		return nil
	}
	return nil
}

// isExplicitStrTag reports whether the node had an explicit !!str tag.
func isExplicitStrTag(n *yaml.Node) bool {
	// yaml.v3 sets Tag to the resolved tag; an explicit "!!str" on something
	// that would otherwise resolve to another type can be detected by re-resolving.
	v := resolvePlainScalar(n.Value)
	_, isStr := v.(string)
	return !isStr
}

func yamlKeyString(k interface{}) string {
	switch t := k.(type) {
	case nil:
		return "null"
	case string:
		return t
	case bool:
		if t {
			return "true"
		}
		return "false"
	case int64:
		return strconv.FormatInt(t, 10)
	case uint64:
		return strconv.FormatUint(t, 10)
	case float64:
		return yamlFormatFloat(t)
	default:
		return fmt.Sprint(t)
	}
}

var (
	yamlIntRe    = regexp.MustCompile(`^[-+]?(0|[1-9][0-9_]*)$`)
	yamlOctLegRe = regexp.MustCompile(`^[-+]?0[0-7_]+$`)
	yamlOctRe    = regexp.MustCompile(`^[-+]?0o[0-7_]+$`)
	yamlHexRe    = regexp.MustCompile(`^[-+]?0x[0-9a-fA-F_]+$`)
	yamlBinRe    = regexp.MustCompile(`^[-+]?0b[01_]+$`)
	yamlFloatRe  = regexp.MustCompile(`^[-+]?([0-9][0-9_]*)?\.[0-9_]+([eE][-+]?[0-9]+)?$`)
	yamlFloat2Re = regexp.MustCompile(`^[-+]?[0-9][0-9_]*\.([eE][-+]?[0-9]+)?$`)
)

// resolvePlainScalar resolves a plain scalar like the goccy yaml library.
func resolvePlainScalar(s string) interface{} {
	switch s {
	case "", "null", "Null", "NULL", "~":
		return nil
	case "true", "True", "TRUE":
		return true
	case "false", "False", "FALSE":
		return false
	case ".inf", ".Inf", ".INF", "+.inf", "+.Inf", "+.INF":
		return math.Inf(1)
	case "-.inf", "-.Inf", "-.INF":
		return math.Inf(-1)
	case ".nan", ".NaN", ".NAN":
		return math.NaN()
	}
	if yamlIsNumber(s) {
		plain := strings.ReplaceAll(s, "_", "")
		switch {
		case yamlHexRe.MatchString(s):
			if v, err := parseIntPrefix(plain, "0x", 16); err == nil {
				return v
			}
		case yamlOctRe.MatchString(s):
			if v, err := parseIntPrefix(plain, "0o", 8); err == nil {
				return v
			}
		case yamlBinRe.MatchString(s):
			if v, err := parseIntPrefix(plain, "0b", 2); err == nil {
				return v
			}
		case yamlOctLegRe.MatchString(s):
			neg := strings.HasPrefix(plain, "-")
			p := strings.TrimLeft(plain, "+-")
			if v, err := strconv.ParseInt(p, 8, 64); err == nil {
				if neg {
					v = -v
				}
				return v
			}
		case yamlIntRe.MatchString(s):
			if v, err := strconv.ParseInt(plain, 10, 64); err == nil {
				return v
			}
			if v, err := strconv.ParseUint(plain, 10, 64); err == nil {
				return v
			}
			if f, err := strconv.ParseFloat(plain, 64); err == nil {
				return f
			}
		default:
			if f, err := strconv.ParseFloat(plain, 64); err == nil {
				return f
			}
		}
	}
	return s
}

func parseIntPrefix(s string, prefix string, base int) (interface{}, error) {
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	} else if strings.HasPrefix(s, "+") {
		s = s[1:]
	}
	s = strings.TrimPrefix(s, prefix)
	v, err := strconv.ParseUint(s, base, 64)
	if err != nil {
		return nil, err
	}
	if neg {
		return -int64(v), nil
	}
	if v <= math.MaxInt64 {
		return int64(v), nil
	}
	return v, nil
}

func yamlIsNumber(s string) bool {
	return yamlIntRe.MatchString(s) || yamlOctLegRe.MatchString(s) || yamlOctRe.MatchString(s) ||
		yamlHexRe.MatchString(s) || yamlBinRe.MatchString(s) || yamlFloatRe.MatchString(s) || yamlFloat2Re.MatchString(s)
}

// yamlFormatFloat formats a float like goccy yaml.
func yamlFormatFloat(f float64) string {
	if math.IsInf(f, 1) {
		return ".inf"
	}
	if math.IsInf(f, -1) {
		return "-.inf"
	}
	if math.IsNaN(f) {
		return ".nan"
	}
	s := strconv.FormatFloat(f, 'g', -1, 64)
	if !strings.Contains(s, ".") && !strings.Contains(s, "e") {
		s += ".0"
	}
	return s
}

var yamlReservedEnc = map[string]bool{
	"null": true, "Null": true, "NULL": true, "~": true,
	"true": true, "True": true, "TRUE": true, "false": true, "False": true, "FALSE": true,
	"y": true, "Y": true, "yes": true, "Yes": true, "YES": true,
	"n": true, "N": true, "no": true, "No": true, "NO": true,
	"on": true, "On": true, "ON": true, "off": true, "Off": true, "OFF": true,
	".inf": true, ".Inf": true, ".INF": true, "-.inf": true, "-.Inf": true, "-.INF": true,
	".nan": true, ".NaN": true, ".NAN": true,
}

// yamlNeedQuoted reports whether a string must be quoted when encoded.
func yamlNeedQuoted(v string) bool {
	if v == "" {
		return true
	}
	if yamlReservedEnc[v] {
		return true
	}
	if yamlIsNumber(v) {
		return true
	}
	switch v[0] {
	case '*', '&', '[', '{', '}', ']', ',', '!', '|', '>', '%', '\'', '"', '@', ' ', '#', '`', '?', ':', '-':
		if v[0] == '-' || v[0] == '?' || v[0] == ':' {
			if len(v) == 1 || v[1] == ' ' {
				return true
			}
		} else {
			return true
		}
	}
	switch v[len(v)-1] {
	case ':', ' ':
		return true
	}
	for i := 0; i < len(v); i++ {
		c := v[i]
		switch c {
		case '\\', '\n', '\r', '\t':
			return true
		case '#':
			if i > 0 && v[i-1] == ' ' {
				return true
			}
		case ':':
			if i+1 < len(v) && v[i+1] == ' ' {
				return true
			}
		}
	}
	return false
}

func yamlQuote(s string) string {
	return strconv.Quote(s)
}

func yamlScalarString(v interface{}) string {
	switch t := v.(type) {
	case nil:
		return "null"
	case string:
		if yamlNeedQuoted(t) {
			return yamlQuote(t)
		}
		return t
	case bool:
		if t {
			return "true"
		}
		return "false"
	case int:
		return strconv.Itoa(t)
	case int64:
		return strconv.FormatInt(t, 10)
	case uint64:
		return strconv.FormatUint(t, 10)
	case float64:
		return yamlFormatFloat(t)
	case time.Time:
		return t.Format(time.RFC3339Nano)
	case []byte:
		return yamlScalarString(strings.ToValidUTF8(string(t), "\uFFFD"))
	default:
		return yamlScalarString(fmt.Sprint(t))
	}
}

// yamlEncodeBlock encodes a value in block style appending to buf.
// indent is the current indentation (number of spaces) for nested content.
func yamlEncodeValue(buf *strings.Builder, v interface{}, indent int, inSeq bool) {
	switch t := v.(type) {
	case *yamlMap:
		if len(t.keys) == 0 {
			buf.WriteString(" {}\n")
			return
		}
		if !inSeq {
			buf.WriteString("\n")
		}
		yamlEncodeMap(buf, t, indent, inSeq)
	case map[string]interface{}:
		m := &yamlMap{}
		keys := make([]string, 0, len(t))
		for k := range t {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			m.add(k, t[k])
		}
		yamlEncodeValue(buf, m, indent, inSeq)
	case []interface{}:
		if len(t) == 0 {
			buf.WriteString(" []\n")
			return
		}
		if !inSeq {
			buf.WriteString("\n")
		}
		yamlEncodeSeq(buf, t, indent, inSeq)
	default:
		buf.WriteString(" ")
		buf.WriteString(yamlScalarString(v))
		buf.WriteString("\n")
	}
}

func yamlEncodeMap(buf *strings.Builder, m *yamlMap, indent int, first bool) {
	for i, k := range m.keys {
		if !(first && i == 0) {
			buf.WriteString(strings.Repeat(" ", indent))
		}
		ks := k
		if yamlNeedQuoted(k) {
			ks = yamlQuote(k)
		}
		buf.WriteString(ks)
		buf.WriteString(":")
		v := m.values[i]
		switch vv := v.(type) {
		case *yamlMap:
			if len(vv.keys) == 0 {
				buf.WriteString(" {}\n")
			} else {
				buf.WriteString("\n")
				yamlEncodeMap(buf, vv, indent+2, false)
			}
		case map[string]interface{}:
			if len(vv) == 0 {
				buf.WriteString(" {}\n")
			} else {
				buf.WriteString("\n")
				yamlEncodeMap(buf, sortedYamlMap(vv), indent+2, false)
			}
		case []interface{}:
			if len(vv) == 0 {
				buf.WriteString(" []\n")
			} else {
				buf.WriteString("\n")
				yamlEncodeSeq(buf, vv, indent, false)
			}
		default:
			buf.WriteString(" ")
			buf.WriteString(yamlScalarString(v))
			buf.WriteString("\n")
		}
	}
}

func sortedYamlMap(t map[string]interface{}) *yamlMap {
	m := &yamlMap{}
	keys := make([]string, 0, len(t))
	for k := range t {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		m.add(k, t[k])
	}
	return m
}

func yamlEncodeSeq(buf *strings.Builder, seq []interface{}, indent int, first bool) {
	for i, v := range seq {
		if !(first && i == 0) {
			buf.WriteString(strings.Repeat(" ", indent))
		}
		buf.WriteString("-")
		switch vv := v.(type) {
		case *yamlMap:
			if len(vv.keys) == 0 {
				buf.WriteString(" {}\n")
			} else {
				buf.WriteString(" ")
				yamlEncodeMap(buf, vv, indent+2, true)
			}
		case map[string]interface{}:
			if len(vv) == 0 {
				buf.WriteString(" {}\n")
			} else {
				buf.WriteString(" ")
				yamlEncodeMap(buf, sortedYamlMap(vv), indent+2, true)
			}
		case []interface{}:
			if len(vv) == 0 {
				buf.WriteString(" []\n")
			} else {
				buf.WriteString(" ")
				yamlEncodeSeq(buf, vv, indent+2, true)
			}
		default:
			buf.WriteString(" ")
			buf.WriteString(yamlScalarString(v))
			buf.WriteString("\n")
		}
	}
}

// yamlFlowJSON renders a nested value in the JSON-like flow style.
func yamlFlowJSON(v interface{}) string {
	var b strings.Builder
	yamlFlowWrite(&b, v)
	return b.String()
}

func yamlFlowWrite(b *strings.Builder, v interface{}) {
	switch t := v.(type) {
	case nil:
		b.WriteString("null")
	case *yamlMap:
		b.WriteString("{")
		idx := make([]int, len(t.keys))
		for i := range idx {
			idx[i] = i
		}
		sort.SliceStable(idx, func(i, j int) bool { return t.keys[idx[i]] < t.keys[idx[j]] })
		for n, i := range idx {
			if n > 0 {
				b.WriteString(", ")
			}
			b.WriteString(strconv.Quote(t.keys[i]))
			b.WriteString(": ")
			yamlFlowWrite(b, t.values[i])
		}
		b.WriteString("}")
	case map[string]interface{}:
		yamlFlowWrite(b, sortedYamlMap(t))
	case []interface{}:
		b.WriteString("[")
		for i, e := range t {
			if i > 0 {
				b.WriteString(", ")
			}
			yamlFlowWrite(b, e)
		}
		b.WriteString("]")
	case string:
		b.WriteString(strconv.Quote(yamlNestedString(t)))
	case bool:
		if t {
			b.WriteString("true")
		} else {
			b.WriteString("false")
		}
	case int64:
		b.WriteString(strconv.FormatInt(t, 10))
	case uint64:
		b.WriteString(strconv.FormatUint(t, 10))
	case float64:
		b.WriteString(yamlFormatFloat(t))
	default:
		b.WriteString(strconv.Quote(fmt.Sprint(t)))
	}
}

// yamlNestedString applies the lossy transformation observed for nested strings.
func yamlNestedString(s string) string {
	if !utf8.ValidString(s) {
		s = strings.ToValidUTF8(s, "\uFFFD")
	}
	s = strings.ReplaceAll(s, "\r\n", "\n")
	s = strings.ReplaceAll(s, "\r", "\n")
	s = strings.ReplaceAll(s, "\t", "")
	return s
}

// yamlFoldMultiline emulates re-parsing a multi-line string as plain YAML.
func yamlFoldMultiline(s string) (string, bool) {
	s = strings.ReplaceAll(s, "\r\n", "\n")
	s = strings.ReplaceAll(s, "\r", "\n")
	lines := strings.Split(s, "\n")
	var out strings.Builder
	pendingBreaks := 0
	started := false
	for i, line := range lines {
		t := strings.TrimSpace(line)
		if strings.HasPrefix(t, "#") && i > 0 {
			// comment: stop here
			break
		}
		if t == "" {
			if started {
				pendingBreaks++
			}
			continue
		}
		if strings.Contains(t, ": ") || strings.HasSuffix(t, ":") {
			if i > 0 {
				return "", false
			}
		}
		if started {
			if pendingBreaks > 0 {
				out.WriteString(strings.Repeat("\n", pendingBreaks))
			} else {
				out.WriteString(" ")
			}
		}
		pendingBreaks = 0
		out.WriteString(t)
		started = true
	}
	return out.String(), true
}
