// yamlMap is an ordered mapping.
type yamlMap struct {
	keys   []string
	values []interface{}
}

func (m *yamlMap) add(k string, v interface{}) {
	m.keys = append(m.keys, k)
	m.values = append(m.values, v)
}

func (m *yamlMap) get(k string) (interface{}, bool) {
	for i := len(m.keys) - 1; i >= 0; i-- {
		if m.keys[i] == k {
			return m.values[i], true
		}
	}
	return nil, false
}

// yamlDecoder decodes YAML documents.
type yamlDecoder struct {
	dec *yaml.Decoder
}

func newYAMLDecoder(b []byte) *yamlDecoder {
	return &yamlDecoder{dec: yaml.NewDecoder(bytes.NewReader(b))}
}

// next decodes the next document. Returns io.EOF at end.
func (d *yamlDecoder) next() (interface{}, error) {
	var node yaml.Node
	if err := d.dec.Decode(&node); err != nil {
		return nil, err
	}
	return nodeToValue(&node), nil
}

func nodeToValue(n *yaml.Node) interface{} {
	switch n.Kind {
	case yaml.DocumentNode:
		if len(n.Content) == 0 {
			return nil
		}
		return nodeToValue(n.Content[0])
	case yaml.MappingNode:
		m := &yamlMap{}
		for i := 0; i+1 < len(n.Content); i += 2 {
			k := nodeToValue(n.Content[i])
			m.add(yamlKeyString(k), nodeToValue(n.Content[i+1]))
		}
		return m
	case yaml.SequenceNode:
		seq := make([]interface{}, 0, len(n.Content))
		for _, c := range n.Content {
			seq = append(seq, nodeToValue(c))
		}
		return seq
	case yaml.ScalarNode:
		if n.Style == yaml.DoubleQuotedStyle || n.Style == yaml.SingleQuotedStyle ||
			n.Style == yaml.LiteralStyle || n.Style == yaml.FoldedStyle {
			return n.Value
		}
		if n.Tag == "!!str" && n.Style == 0 && n.ShortTag() == "!!str" && strings.HasPrefix(n.Tag, "!!") && n.Tag != "" && isExplicitStrTag(n) {
			return n.Value
		}
		return resolvePlainScalar(n.Value)
	case yaml.AliasNode:
		if n.Alias != nil {
			return nodeToValue(n.Alias)
		}
		return nil
	}
	return nil
}

// isExplicitStrTag reports whether the node had an explicit !!str tag.
func isExplicitStrTag(n *yaml.Node) bool {
	// yaml.v3 sets Tag to the resolved tag; an explicit "!!str" on something
	// that would otherwise resolve to another type can be detected by re-resolving.
	v := resolvePlainScalar(n.Value)
	_, isStr := v.(string)
	return !isStr
}

func yamlKeyString(k interface{}) string {
	switch t := k.(type) {
	case nil:
		return "null"
	case string:
		return t
	case bool:
		if t {
			return "true"
		}
		return "false"
	case int64:
		return strconv.FormatInt(t, 10)
	case uint64:
		return strconv.FormatUint(t, 10)
	case float64:
		return yamlFormatFloat(t)
	default:
		return fmt.Sprint(t)
	}
}

var (
	yamlIntRe    = regexp.MustCompile(`^[-+]?(0|[1-9][0-9_]*)$`)
	yamlOctLegRe = regexp.MustCompile(`^[-+]?0[0-7_]+$`)
	yamlOctRe    = regexp.MustCompile(`^[-+]?0o[0-7_]+$`)
	yamlHexRe    = regexp.MustCompile(`^[-+]?0x[0-9a-fA-F_]+$`)
	yamlBinRe    = regexp.MustCompile(`^[-+]?0b[01_]+$`)
	yamlFloatRe  = regexp.MustCompile(`^[-+]?([0-9][0-9_]*)?\.[0-9_]+([eE][-+]?[0-9]+)?$`)
	yamlFloat2Re = regexp.MustCompile(`^[-+]?[0-9][0-9_]*\.([eE][-+]?[0-9]+)?$`)
)

// resolvePlainScalar resolves a plain scalar like the goccy yaml library.
func resolvePlainScalar(s string) interface{} {
	switch s {
	case "", "null", "Null", "NULL", "~":
		return nil
	case "true", "True", "TRUE":
		return true
	case "false", "False", "FALSE":
		return false
	case ".inf", ".Inf", ".INF", "+.inf", "+.Inf", "+.INF":
		return math.Inf(1)
	case "-.inf", "-.Inf", "-.INF":
		return math.Inf(-1)
	case ".nan", ".NaN", ".NAN":
		return math.NaN()
	}
	if yamlIsNumber(s) {
		plain := strings.ReplaceAll(s, "_", "")
		switch {
		case yamlHexRe.MatchString(s):
			if v, err := parseIntPrefix(plain, "0x", 16); err == nil {
				return v
			}
		case yamlOctRe.MatchString(s):
			if v, err := parseIntPrefix(plain, "0o", 8); err == nil {
				return v
			}
		case yamlBinRe.MatchString(s):
			if v, err := parseIntPrefix(plain, "0b", 2); err == nil {
				return v
			}
		case yamlOctLegRe.MatchString(s):
			neg := strings.HasPrefix(plain, "-")
			p := strings.TrimLeft(plain, "+-")
			if v, err := strconv.ParseInt(p, 8, 64); err == nil {
				if neg {
					v = -v
				}
				return v
			}
		case yamlIntRe.MatchString(s):
			if v, err := strconv.ParseInt(plain, 10, 64); err == nil {
				return v
			}
			if v, err := strconv.ParseUint(plain, 10, 64); err == nil {
				return v
			}
			if f, err := strconv.ParseFloat(plain, 64); err == nil {
				return f
			}
		default:
			if f, err := strconv.ParseFloat(plain, 64); err == nil {
				return f
			}
		}
	}
	return s
}

func parseIntPrefix(s string, prefix string, base int) (interface{}, error) {
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	} else if strings.HasPrefix(s, "+") {
		s = s[1:]
	}
	s = strings.TrimPrefix(s, prefix)
	v, err := strconv.ParseUint(s, base, 64)
	if err != nil {
		return nil, err
	}
	if neg {
		return -int64(v), nil
	}
	if v <= math.MaxInt64 {
		return int64(v), nil
	}
	return v, nil
}

func yamlIsNumber(s string) bool {
	return yamlIntRe.MatchString(s) || yamlOctLegRe.MatchString(s) || yamlOctRe.MatchString(s) ||
