func sortedYamlMap(t map[string]interface{}) *yamlMap {
	m := &yamlMap{}
	keys := make([]string, 0, len(t))
	for k := range t {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		m.add(k, t[k])
	}
	return m
}

func yamlEncodeSeq(buf *strings.Builder, seq []interface{}, indent int, first bool) {
	for i, v := range seq {
		if !(first && i == 0) {
			buf.WriteString(strings.Repeat(" ", indent))
		}
		buf.WriteString("-")
		switch vv := v.(type) {
		case *yamlMap:
			if len(vv.keys) == 0 {
				buf.WriteString(" {}\n")
			} else {
				buf.WriteString(" ")
				yamlEncodeMap(buf, vv, indent+2, true)
			}
		case map[string]interface{}:
			if len(vv) == 0 {
				buf.WriteString(" {}\n")
			} else {
				buf.WriteString(" ")
				yamlEncodeMap(buf, sortedYamlMap(vv), indent+2, true)
			}
		case []interface{}:
			if len(vv) == 0 {
				buf.WriteString(" []\n")
			} else {
				buf.WriteString(" ")
				yamlEncodeSeq(buf, vv, indent+2, true)
			}
		default:
			buf.WriteString(" ")
			buf.WriteString(yamlScalarString(v))
			buf.WriteString("\n")
		}
	}
}

// yamlFlowJSON renders a nested value in the JSON-like flow style.
func yamlFlowJSON(v interface{}) string {
	var b strings.Builder
	yamlFlowWrite(&b, v)
	return b.String()
}

func yamlFlowWrite(b *strings.Builder, v interface{}) {
	switch t := v.(type) {
	case nil:
		b.WriteString("null")
	case *yamlMap:
		b.WriteString("{")
		idx := make([]int, len(t.keys))
		for i := range idx {
			idx[i] = i
		}
		sort.SliceStable(idx, func(i, j int) bool { return t.keys[idx[i]] < t.keys[idx[j]] })
		for n, i := range idx {
			if n > 0 {
				b.WriteString(", ")
			}
			b.WriteString(strconv.Quote(t.keys[i]))
			b.WriteString(": ")
			yamlFlowWrite(b, t.values[i])
		}
		b.WriteString("}")
	case map[string]interface{}:
		yamlFlowWrite(b, sortedYamlMap(t))
	case []interface{}:
		b.WriteString("[")
		for i, e := range t {
			if i > 0 {
				b.WriteString(", ")
			}
			yamlFlowWrite(b, e)
		}
		b.WriteString("]")
	case string:
		b.WriteString(strconv.Quote(yamlNestedString(t)))
	case bool:
		if t {
			b.WriteString("true")
		} else {
			b.WriteString("false")
		}
	case int64:
		b.WriteString(strconv.FormatInt(t, 10))
	case uint64:
		b.WriteString(strconv.FormatUint(t, 10))
	case float64:
		b.WriteString(yamlFormatFloat(t))
	default:
		b.WriteString(strconv.Quote(fmt.Sprint(t)))
	}
}

// yamlNestedString applies the lossy transformation observed for nested strings.
func yamlNestedString(s string) string {
	if !utf8.ValidString(s) {
		s = strings.ToValidUTF8(s, "\uFFFD")
	}
	s = strings.ReplaceAll(s, "\r\n", "\n")
	s = strings.ReplaceAll(s, "\r", "\n")
	s = strings.ReplaceAll(s, "\t", "")
	return s
}

// yamlFoldMultiline emulates re-parsing a multi-line string as plain YAML.
func yamlFoldMultiline(s string) (string, bool) {
	s = strings.ReplaceAll(s, "\r\n", "\n")
	s = strings.ReplaceAll(s, "\r", "\n")
	lines := strings.Split(s, "\n")
	var out strings.Builder
	pendingBreaks := 0
	started := false
	for i, line := range lines {
		t := strings.TrimSpace(line)
		if strings.HasPrefix(t, "#") && i > 0 {
			// comment: stop here
			break
		}
		if t == "" {
			if started {
				pendingBreaks++
			}
			continue
		}
		if strings.Contains(t, ": ") || strings.HasSuffix(t, ":") {
			if i > 0 {
				return "", false
			}
		}
		if started {
			if pendingBreaks > 0 {
				out.WriteString(strings.Repeat("\n", pendingBreaks))
			} else {
				out.WriteString(" ")
			}
		}
		pendingBreaks = 0
		out.WriteString(t)
		started = true
	}
	return out.String(), true
}
