// YAMLReader reads YAML documents.
type YAMLReader struct {
	dec       *yaml.Decoder
	preRead   []map[string]interface{}
	names     []string
	types     []string
	inNULL    string
	needNULL  bool
	limitRead bool
}

// NewYAMLReader creates a YAML reader.
func NewYAMLReader(reader io.Reader, opts *ReadOpts) (*YAMLReader, error) {
	r := &YAMLReader{}
	r.dec = yaml.NewDecoder(reader)
	r.inNULL = opts.InNULL
	r.needNULL = opts.InNeedNULL

	preRead := opts.InPreRead
	if opts.InLimitRead > 0 {
		preRead = opts.InLimitRead + opts.InSkip
		r.limitRead = true
	}

	for i := 0; i < opts.InSkip; i++ {
		if _, err := r.next(); err != nil {
			debugf("ERROR: skip error %s", err)
			break
		}
	}

	for i := 0; i < preRead; i++ {
		top, err := r.next()
		if err != nil {
			if err == io.EOF {
				break
			}
			return r, fmt.Errorf("%w: %s", errInvalidYAML, err)
		}
		r.readAhead(top)
	}
	r.types = make([]string, len(r.names))
	for i := range r.types {
		r.types[i] = "text"
	}
	return r, nil
}

func (r *YAMLReader) next() (interface{}, error) {
	var node yaml.Node
	if err := r.dec.Decode(&node); err != nil {
		return nil, err
	}
	return nodeToValue(&node), nil
}

func (r *YAMLReader) readAhead(top interface{}) {
	switch m := top.(type) {
	case []interface{}:
		for _, v := range m {
			switch mm := v.(type) {
			case *yamlMap:
				r.preRead = append(r.preRead, r.objectRow(mm))
			default:
				r.preRead = append(r.preRead, r.etcRow(mm))
			}
		}
	case *yamlMap:
		r.preRead = append(r.preRead, r.objectRow(m))
	default:
		r.preRead = append(r.preRead, r.etcRow(m))
	}
}

func (r *YAMLReader) addName(name string) {
	for _, n := range r.names {
		if n == name {
			return
		}
	}
	r.names = append(r.names, name)
}

func (r *YAMLReader) objectRow(obj *yamlMap) map[string]interface{} {
	// Use a Go map so that key iteration order matches map semantics.
	gm := make(map[string]interface{}, len(obj.keys))
	for i, k := range obj.keys {
		gm[k] = obj.values[i]
	}
	row := make(map[string]interface{}, len(gm))
	for k, v := range gm {
		r.addName(k)
		row[k] = r.yamlString(v)
	}
	return row
}

func (r *YAMLReader) etcRow(val interface{}) map[string]interface{} {
	r.addName("c1")
	row := make(map[string]interface{}, 1)
	row["c1"] = r.yamlString(val)
	return row
}

func (r *YAMLReader) yamlString(val interface{}) interface{} {
	var str string
	switch t := val.(type) {
	case nil:
		return nil
	case string:
		if strings.ContainsAny(t, "\n\r") {
			folded, ok := yamlFoldMultiline(t)
			if !ok {
				str = t
			} else if folded == "" {
				str = "null"
			} else {
				str = strconv.Quote(folded)
			}
		} else {
			str = t
		}
	case bool:
		if t {
			str = "true"
		} else {
			str = "false"
		}
	case int64:
		str = strconv.FormatInt(t, 10)
	case uint64:
		str = strconv.FormatUint(t, 10)
	case float64:
		str = fmt.Sprint(t)
	case *yamlMap, []interface{}:
		str = yamlFlowJSON(t)
	default:
		str = fmt.Sprint(t)
	}
	if r.needNULL && str == r.inNULL {
		return nil
	}
	return str
}

// Names returns column names.
func (r *YAMLReader) Names() ([]string, error) {
	if len(r.names) == 0 {
		return nil, errInvalidNames
	}
	return r.names, nil
}

// Types returns column types.
func (r *YAMLReader) Types() ([]string, error) {
	return r.types, nil
}

// PreReadRow returns pre-read rows.
func (r *YAMLReader) PreReadRow() [][]interface{} {
	rows := make([][]interface{}, len(r.preRead))
	for n, m := range r.preRead {
		rows[n] = make([]interface{}, len(r.names))
		for i, name := range r.names {
			rows[n][i] = m[name]
		}
	}
	return rows
}

// ReadRow reads the next row.
func (r *YAMLReader) ReadRow(row []interface{}) ([]interface{}, error) {
	if r.limitRead {
		return nil, io.EOF
	}
	top, err := r.next()
	if err != nil {
		if err == io.EOF {
			return nil, io.EOF
		}
		return nil, fmt.Errorf("%w: %s", errInvalidYAML, err)
	}
	switch m := top.(type) {
	case *yamlMap:
		for i, name := range r.names {
			if v, ok := m.get(name); ok {
				row[i] = r.yamlString(v)
			} else {
				row[i] = nil
			}
		}
	default:
		for i := range row {
			row[i] = nil
		}
		if len(row) > 0 {
			row[0] = r.yamlString(top)
		}
	}
	return row, nil
}
