package main

import (
	"fmt"
	"io"
	"regexp"
	"strconv"
	"strings"
)

// AnalyzeOpts are options for analysis.
type AnalyzeOpts struct {
	Command   string
	Quote     string
	Detail    bool
	OutStream io.Writer
	PreRead   int
}

// NewAnalyzeOpts returns default options.
func NewAnalyzeOpts() *AnalyzeOpts {
	return &AnalyzeOpts{Command: "trdsql", Quote: "\\`", Detail: true, PreRead: 0}
}

func quoteOpts(opts *AnalyzeOpts, driver string) *AnalyzeOpts {
	if driver == "postgres" {
		opts.Quote = `\"`
	}
	return opts
}

func optsCommand(opts *AnalyzeOpts, args []string) *AnalyzeOpts {
	command := args[0]
	omitFlag := false
	for _, arg := range args[1:] {
		if omitFlag {
			omitFlag = false
			continue
		}
		if arg == "-a" || arg == "-A" {
			omitFlag = true
			continue
		}
		if len(arg) <= 1 || arg[0] != '-' {
			arg = quotedArg(arg)
		}
		command += " " + arg
	}
	opts.Command = command
	return opts
}

func quotedArg(arg string) string {
	if _, err := strconv.Atoi(arg); err == nil {
		return arg
	}
