		g.preLines = append(g.preLines, line)
	}
	g.pos = gwPositions(g.preLines, g.header, g.minLines)
}

func (g *guessWidth) read() ([]string, error) {
	if !g.scanned {
		g.scan(g.scanNum)
	}
	var line string
	if g.preCount < len(g.preLines) {
		line = g.preLines[g.preCount]
		g.preCount++
	} else {
		l, err := g.readLine()
		if err != nil {
			return nil, err
		}
		line = l
	}
	return gwSplit(line, g.pos, g.trimSpace), nil
}

func gwPositions(lines []string, header int, minLines int) []int {
	var blanks []int
	for n, line := range lines {
		if n < header {
			continue
		}
		if n == header {
			blanks = gwLookupBlanks(strings.TrimSuffix(line, " "))
			continue
		}
		blanks = gwCountBlanks(blanks, strings.TrimSuffix(line, " "))
	}
	return gwPositionsFromBlanks(blanks, minLines)
}

func gwLookupBlanks(str string) []int {
	blanks := make([]int, 0, len(str))
	first := true
	for _, v := range str {
		if v != ' ' {
			first = false
			blanks = append(blanks, 0)
			if runewidth.RuneWidth(v) == 2 {
				blanks = append(blanks, 0)
			}
			continue
		}
		if first {
			blanks = append(blanks, 0)
			continue
		}
		blanks = append(blanks, 1)
	}
	return blanks
}

func gwCountBlanks(blanks []int, str string) []int {
	n := 0
	for _, v := range str {
		if n >= len(blanks) {
			break
		}
		if v == ' ' && blanks[n] > 0 {
			blanks[n]++
		}
		n++
		if runewidth.RuneWidth(v) == 2 {
			n++
		}
	}
	return blanks
}

func gwPositionsFromBlanks(blanks []int, minLines int) []int {
	max := minLines
	p := 0
	var pos []int
	for n, v := range blanks {
		if v >= max {
			max = v
			p = n
		}
		if v == 0 {
			max = minLines
			if p > 0 {
				pos = append(pos, p)
				p = 0
			}
		}
	}
	return pos
}

func gwSeparatorPosition(lr []rune, p int, pos []int, n int) int {
	if unicode.IsSpace(lr[p]) {
		return p
	}
	f := p
	fp := 0
	for ; f < len(lr) && !unicode.IsSpace(lr[f]); f++ {
		fp++
	}
	b := p
	bp := 0
	for ; b > 0 && !unicode.IsSpace(lr[b]); b-- {
		bp++
	}
	if b == 0 && !unicode.IsSpace(lr[0]) {
		return f
	}
	if n+1 < len(pos) && f >= pos[n+1] {
		return b
	}
	if n > 0 && b <= pos[n-1] {
		return f
	}
	if fp < bp {
		return f
	}
	return b
}

func gwSplit(line string, pos []int, trimSpace bool) []string {
	n := 0
	start := 0
	columns := make([]string, len(pos)+1)
	lr := []rune(line)
	w := 0
	for p := 0; p < len(lr); p++ {
		if n > len(pos)-1 {
			break
		}
		if pos[n] <= w {
			end := gwSeparatorPosition(lr, p, pos, n)
			if start > end {
				break
			}
			columns[n] = string(lr[start:end])
			if trimSpace {
				columns[n] = strings.TrimSpace(columns[n])
			}
			n++
			start = end
			p = end - 1
			w = gwWidth(lr[:end])
			continue
		}
		w += runewidth.RuneWidth(lr[p])
	}
	if start <= len(lr) {
		columns[n] = string(lr[start:])
		if trimSpace {
			columns[n] = strings.TrimSpace(columns[n])
		}
	}
	return columns
}

func gwWidth(lr []rune) int {
	w := 0
	for _, r := range lr {
		w += runewidth.RuneWidth(r)
	}
	return w
}

// GWReader reads fixed width text.
type GWReader struct {
	reader    *guessWidth
	names     []string
	types     []string
	preRead   [][]string
	inNULL    string
	needNULL  bool
	limitRead bool
}

// NewGWReader creates a width-format reader.
func NewGWReader(reader io.Reader, opts *ReadOpts) (*GWReader, error) {
	r := &GWReader{}
	r.reader = newGuessWidth(reader)
	r.reader.header = opts.InSkip
	r.inNULL = opts.InNULL
	r.needNULL = opts.InNeedNULL

	preRead := opts.InPreRead
	if opts.InLimitRead > 0 {
		preRead = opts.InLimitRead + opts.InSkip
		r.limitRead = true
	}
	scanNum := 100
	if preRead+1 > scanNum {
		scanNum = preRead + 1
	}
	r.reader.scan(scanNum)
	names, err := r.reader.read()
	if err != nil {
		if err == io.EOF {
			return r, nil
		}
		return nil, err
	}
	r.names = names
	for i := 0; i < preRead; i++ {
		row, err := r.reader.read()
		if err != nil {
			break
		}
		r.preRead = append(r.preRead, row)
	}
	r.types = make([]string, len(r.names))
	for i := range r.types {
		r.types[i] = "text"
	}
	return r, nil
}

// Names returns column names.
func (r *GWReader) Names() ([]string, error) {
	if len(r.names) == 0 {
		return nil, errInvalidNames
	}
	return r.names, nil
}

// Types returns column types.
func (r *GWReader) Types() ([]string, error) {
	return r.types, nil
}

func (r *GWReader) convert(s string) interface{} {
	if r.needNULL && s == r.inNULL {
		return nil
	}
	return s
}

// PreReadRow returns pre-read rows.
func (r *GWReader) PreReadRow() [][]interface{} {
	rows := make([][]interface{}, len(r.preRead))
	for n, row := range r.preRead {
		rows[n] = make([]interface{}, len(r.names))
		for i := range r.names {
			if i < len(row) {
				rows[n][i] = r.convert(row[i])
			}
		}
	}
	return rows
}

// ReadRow reads the next row.
func (r *GWReader) ReadRow(row []interface{}) ([]interface{}, error) {
	if r.limitRead {
		return nil, io.EOF
	}
	rec, err := r.reader.read()
	if err != nil {
		return row, err
	}
	for i := range row {
		if i < len(rec) {
			row[i] = r.convert(rec[i])
		} else {
			row[i] = nil
		}
	}
	return row, nil
}
