// ---- lexer ----

type jqTokenKind int

const (
	tkEOF jqTokenKind = iota
	tkIdent
	tkField // .foo
	tkDot
	tkDotDot
	tkNumber
	tkString
	tkVar
	tkOp
	tkLParen
	tkRParen
	tkLBracket
	tkRBracket
	tkLBrace
	tkRBrace
	tkComma
	tkPipe
	tkColon
	tkQuestion
	tkKeyword
)

type jqToken struct {
	kind jqTokenKind
	val  string
}

var jqKeywords = map[string]bool{
	"if": true, "then": true, "elif": true, "else": true, "end": true,
	"and": true, "or": true, "not": false, "as": true, "reduce": true, "foreach": true,
	"try": true, "catch": true, "def": true,
}

func jqLex(s string) ([]jqToken, error) {
	var toks []jqToken
	i := 0
	for i < len(s) {
		c := s[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r':
			i++
		case c == '.':
			if i+1 < len(s) && s[i+1] == '.' {
				toks = append(toks, jqToken{tkDotDot, ".."})
				i += 2
			} else if i+1 < len(s) && (isIdentStart(s[i+1])) {
				j := i + 1
				for j < len(s) && isIdentChar(s[j]) {
					j++
				}
				toks = append(toks, jqToken{tkField, s[i+1 : j]})
				i = j
			} else if i+1 < len(s) && s[i+1] == '"' {
				str, n, err := jqLexString(s[i+1:])
				if err != nil {
					return nil, err
				}
				toks = append(toks, jqToken{tkField, str})
				i += 1 + n
			} else {
				toks = append(toks, jqToken{tkDot, "."})
				i++
			}
		case c == '$':
			j := i + 1
			for j < len(s) && isIdentChar(s[j]) {
				j++
			}
			toks = append(toks, jqToken{tkVar, s[i+1 : j]})
			i = j
		case c == '"':
			str, n, err := jqLexString(s[i:])
			if err != nil {
				return nil, err
			}
			toks = append(toks, jqToken{tkString, str})
			i += n
		case c >= '0' && c <= '9':
			j := i
			for j < len(s) && (s[j] >= '0' && s[j] <= '9' || s[j] == '.') {
				j++
			}
			if j < len(s) && (s[j] == 'e' || s[j] == 'E') {
				j++
				if j < len(s) && (s[j] == '+' || s[j] == '-') {
					j++
				}
				for j < len(s) && s[j] >= '0' && s[j] <= '9' {
					j++
				}
			}
			toks = append(toks, jqToken{tkNumber, s[i:j]})
			i = j
		case isIdentStart(c):
			j := i
			for j < len(s) && (isIdentChar(s[j]) || s[j] == ':' && j+1 < len(s) && s[j+1] == ':') {
				if s[j] == ':' {
					j += 2
				} else {
					j++
				}
			}
			word := s[i:j]
			if jqKeywords[word] {
				toks = append(toks, jqToken{tkKeyword, word})
			} else {
				toks = append(toks, jqToken{tkIdent, word})
			}
			i = j
		case c == '(':
			toks = append(toks, jqToken{tkLParen, "("})
			i++
		case c == ')':
			toks = append(toks, jqToken{tkRParen, ")"})
			i++
		case c == '[':
			toks = append(toks, jqToken{tkLBracket, "["})
			i++
		case c == ']':
			toks = append(toks, jqToken{tkRBracket, "]"})
			i++
		case c == '{':
			toks = append(toks, jqToken{tkLBrace, "{"})
			i++
		case c == '}':
			toks = append(toks, jqToken{tkRBrace, "}"})
			i++
		case c == ',':
			toks = append(toks, jqToken{tkComma, ","})
			i++
		case c == '|':
			if i+1 < len(s) && s[i+1] == '=' {
				toks = append(toks, jqToken{tkOp, "|="})
				i += 2
			} else {
				toks = append(toks, jqToken{tkPipe, "|"})
				i++
			}
		case c == ':':
			toks = append(toks, jqToken{tkColon, ":"})
			i++
		case c == '?':
			if i+1 < len(s) && s[i+1] == '/' && i+2 < len(s) && s[i+2] == '/' {
				toks = append(toks, jqToken{tkOp, "?//"})
				i += 3
			} else {
				toks = append(toks, jqToken{tkQuestion, "?"})
				i++
			}
		default:
			ops := []string{"==", "!=", "<=", ">=", "//", "+", "-", "*", "/", "%", "<", ">", "="}
			matched := false
			for _, op := range ops {
				if strings.HasPrefix(s[i:], op) {
					toks = append(toks, jqToken{tkOp, op})
					i += len(op)
					matched = true
					break
				}
			}
			if !matched {
				return nil, fmt.Errorf("unexpected token %q", string(c))
			}
		}
	}
	toks = append(toks, jqToken{tkEOF, ""})
	return toks, nil
}

func isIdentStart(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

func isIdentChar(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9')
}

func jqLexString(s string) (string, int, error) {
	// s starts with '"'
	var b strings.Builder
	i := 1
	for i < len(s) {
		c := s[i]
		if c == '"' {
			return b.String(), i + 1, nil
		}
		if c == '\\' && i+1 < len(s) {
			i++
			switch s[i] {
			case 'n':
				b.WriteByte('\n')
			case 't':
				b.WriteByte('\t')
			case 'r':
				b.WriteByte('\r')
			case 'b':
				b.WriteByte('\b')
			case 'f':
				b.WriteByte('\f')
			case '/':
				b.WriteByte('/')
			case '\\':
				b.WriteByte('\\')
			case '"':
				b.WriteByte('"')
			case 'u':
				if i+4 < len(s) {
					if v, err := strconv.ParseUint(s[i+1:i+5], 16, 32); err == nil {
						b.WriteRune(rune(v))
						i += 4
					}
				}
			default:
				b.WriteByte(s[i])
			}
			i++
			continue
		}
		b.WriteByte(c)
		i++
	}
	return "", 0, fmt.Errorf("unterminated string")
}

// ---- parser ----

type jqParser struct {
	toks []jqToken
	pos  int
}

func (p *jqParser) peek() jqToken { return p.toks[p.pos] }
func (p *jqParser) next() jqToken {
	t := p.toks[p.pos]
	if t.kind != tkEOF {
		p.pos++
	}
	return t
}

func (p *jqParser) expect(kind jqTokenKind, val string) error {
	t := p.next()
	if t.kind != kind || (val != "" && t.val != val) {
		if t.kind == tkEOF {
			return fmt.Errorf("unexpected EOF")
		}
		return fmt.Errorf("unexpected token %q", t.val)
	}
	return nil
}

func compileJQ(q string) (jqQuery, error) {
	toks, err := jqLex(q)
	if err != nil {
		return nil, err
	}
	p := &jqParser{toks: toks}
	node, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	if p.peek().kind != tkEOF {
		return nil, fmt.Errorf("unexpected token %q", p.peek().val)
	}
	return &jqProgram{root: node, src: q}, nil
}

// pipe: comma ('|' pipe)?
func (p *jqParser) parsePipe() (jqNode, error) {
	left, err := p.parseComma()
	if err != nil {
		return nil, err
	}
	if p.peek().kind == tkKeyword && p.peek().val == "as" {
		p.next()
		v := p.next()
		if v.kind != tkVar {
			return nil, fmt.Errorf("unexpected token %q", v.val)
		}
		if err := p.expect(tkPipe, ""); err != nil {
			return nil, err
		}
		body, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		return &jqBind{src: left, name: v.val, body: body}, nil
	}
	if p.peek().kind == tkPipe {
		p.next()
		right, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		return &jqPipe{left: left, right: right}, nil
	}
	return left, nil
}

func (p *jqParser) parseComma() (jqNode, error) {
	left, err := p.parseAlt()
	if err != nil {
		return nil, err
	}
	for p.peek().kind == tkComma {
		p.next()
		right, err := p.parseAlt()
		if err != nil {
			return nil, err
		}
		left = &jqComma{left: left, right: right}
	}
	return left, nil
}

func (p *jqParser) parseAlt() (jqNode, error) {
	left, err := p.parseOr()
	if err != nil {
		return nil, err
	}
	for p.peek().kind == tkOp && p.peek().val == "//" {
		p.next()
		right, err := p.parseOr()
		if err != nil {
			return nil, err
		}
		left = &jqAlt{left: left, right: right}
	}
	return left, nil
}

func (p *jqParser) parseOr() (jqNode, error) {
	left, err := p.parseAnd()
	if err != nil {
		return nil, err
	}
	for p.peek().kind == tkKeyword && p.peek().val == "or" {
		p.next()
		right, err := p.parseAnd()
		if err != nil {
			return nil, err
		}
		left = &jqLogic{op: "or", left: left, right: right}
	}
	return left, nil
}

func (p *jqParser) parseAnd() (jqNode, error) {
	left, err := p.parseCompare()
	if err != nil {
		return nil, err
	}
	for p.peek().kind == tkKeyword && p.peek().val == "and" {
		p.next()
		right, err := p.parseCompare()
		if err != nil {
			return nil, err
		}
		left = &jqLogic{op: "and", left: left, right: right}
	}
	return left, nil
}

func (p *jqParser) parseCompare() (jqNode, error) {
	left, err := p.parseAdd()
	if err != nil {
		return nil, err
	}
	if p.peek().kind == tkOp {
		switch p.peek().val {
		case "==", "!=", "<", "<=", ">", ">=":
			op := p.next().val
			right, err := p.parseAdd()
			if err != nil {
				return nil, err
			}
			return &jqBinOp{op: op, left: left, right: right}, nil
		}
	}
	return left, nil
}

func (p *jqParser) parseAdd() (jqNode, error) {
	left, err := p.parseMul()
	if err != nil {
		return nil, err
	}
	for p.peek().kind == tkOp && (p.peek().val == "+" || p.peek().val == "-") {
		op := p.next().val
		right, err := p.parseMul()
		if err != nil {
			return nil, err
		}
		left = &jqBinOp{op: op, left: left, right: right}
	}
	return left, nil
}

func (p *jqParser) parseMul() (jqNode, error) {
	left, err := p.parseUnary()
	if err != nil {
		return nil, err
	}
	for p.peek().kind == tkOp && (p.peek().val == "*" || p.peek().val == "/" || p.peek().val == "%") {
		op := p.next().val
		right, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		left = &jqBinOp{op: op, left: left, right: right}
	}
	return left, nil
}

func (p *jqParser) parseUnary() (jqNode, error) {
	if p.peek().kind == tkOp && p.peek().val == "-" {
		p.next()
		operand, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		return &jqNeg{operand: operand}, nil
	}
	return p.parsePostfix()
}

func (p *jqParser) parsePostfix() (jqNode, error) {
	node, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}
	for {
		t := p.peek()
		switch {
		case t.kind == tkField:
			p.next()
			node = &jqIndex{src: node, key: &jqLiteral{val: t.val}}
		case t.kind == tkDot && p.toks[p.pos+1].kind == tkString:
			p.next()
			s := p.next()
			node = &jqIndex{src: node, key: &jqLiteral{val: s.val}}
		case t.kind == tkDot && p.toks[p.pos+1].kind == tkLBracket:
			p.next()
			n, err := p.parseBracket(node)
			if err != nil {
				return nil, err
			}
			node = n
		case t.kind == tkLBracket:
			n, err := p.parseBracket(node)
			if err != nil {
				return nil, err
			}
			node = n
		case t.kind == tkQuestion:
			p.next()
			node = &jqTry{body: node}
		default:
			return node, nil
		}
	}
}

func (p *jqParser) parseBracket(src jqNode) (jqNode, error) {
	if err := p.expect(tkLBracket, ""); err != nil {
		return nil, err
	}
	if p.peek().kind == tkRBracket {
		p.next()
		return &jqIterate{src: src}, nil
	}
	var from, to jqNode
	var err error
	if p.peek().kind != tkColon {
		from, err = p.parsePipe()
		if err != nil {
			return nil, err
		}
	}
	if p.peek().kind == tkColon {
		p.next()
		if p.peek().kind != tkRBracket {
			to, err = p.parsePipe()
			if err != nil {
				return nil, err
			}
		}
		if err := p.expect(tkRBracket, ""); err != nil {
			return nil, err
		}
		return &jqSlice{src: src, from: from, to: to}, nil
	}
	if err := p.expect(tkRBracket, ""); err != nil {
		return nil, err
	}
	return &jqIndex{src: src, key: from}, nil
}

func (p *jqParser) parsePrimary() (jqNode, error) {
	t := p.next()
	switch t.kind {
	case tkDot:
		if p.peek().kind == tkString {
			s := p.next()
			return &jqIndex{src: &jqIdentity{}, key: &jqLiteral{val: s.val}}, nil
		}
		if p.peek().kind == tkLBracket {
			return p.parseBracket(&jqIdentity{})
		}
		return &jqIdentity{}, nil
	case tkDotDot:
		return &jqRecurse{}, nil
	case tkField:
		return &jqIndex{src: &jqIdentity{}, key: &jqLiteral{val: t.val}}, nil
	case tkNumber:
		return &jqLiteral{val: jqNumber(t.val)}, nil
	case tkString:
		return &jqLiteral{val: t.val}, nil
	case tkVar:
		return &jqVarRef{name: t.val}, nil
	case tkLParen:
		node, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		if err := p.expect(tkRParen, ""); err != nil {
			return nil, err
		}
		return node, nil
	case tkLBracket:
		if p.peek().kind == tkRBracket {
			p.next()
			return &jqArrayCons{}, nil
		}
		body, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		if err := p.expect(tkRBracket, ""); err != nil {
			return nil, err
		}
		return &jqArrayCons{body: body}, nil
	case tkLBrace:
		return p.parseObject()
	case tkKeyword:
		switch t.val {
		case "if":
			return p.parseIf()
		case "try":
			body, err := p.parsePostfix()
			if err != nil {
				return nil, err
			}
			var catch jqNode
			if p.peek().kind == tkKeyword && p.peek().val == "catch" {
				p.next()
				catch, err = p.parsePostfix()
				if err != nil {
					return nil, err
				}
			}
			return &jqTry{body: body, catch: catch}, nil
		case "reduce":
			src, err := p.parsePostfix()
			if err != nil {
				return nil, err
			}
			if err := p.expect(tkKeyword, "as"); err != nil {
				return nil, err
			}
			v := p.next()
			if v.kind != tkVar {
				return nil, fmt.Errorf("unexpected token %q", v.val)
			}
			if err := p.expect(tkLParen, ""); err != nil {
				return nil, err
			}
			init, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			if err := p.expect(tkColon, ""); err != nil {
				return nil, err
			}
			update, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			if err := p.expect(tkRParen, ""); err != nil {
				return nil, err
			}
			return &jqReduce{src: src, name: v.val, init: init, update: update}, nil
		}
		return nil, fmt.Errorf("unexpected token %q", t.val)
	case tkIdent:
		switch t.val {
		case "true":
			return &jqLiteral{val: true}, nil
		case "false":
			return &jqLiteral{val: false}, nil
		case "null":
			return &jqLiteral{val: nil}, nil
		}
		var args []jqNode
		if p.peek().kind == tkLParen {
			p.next()
			for {
				arg, err := p.parsePipe()
				if err != nil {
					return nil, err
				}
				args = append(args, arg)
				if p.peek().kind == tkOp && p.peek().val == ";" {
					p.next()
					continue
				}
				if p.peek().kind == tkColon {
					// not valid
				}
				break
			}
			// support ';' separated args: lexer doesn't produce ';' token; handle via raw scan
			if err := p.expect(tkRParen, ""); err != nil {
				return nil, err
			}
		}
		if _, ok := jqFuncs[t.val]; !ok {
			return nil, fmt.Errorf("function not defined: %s/%d", t.val, len(args))
		}
		return &jqFuncCall{name: t.val, args: args}, nil
	case tkEOF:
		return nil, fmt.Errorf("unexpected EOF")
	}
	return nil, fmt.Errorf("unexpected token %q", t.val)
}

func (p *jqParser) parseIf() (jqNode, error) {
	cond, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	if err := p.expect(tkKeyword, "then"); err != nil {
		return nil, err
	}
	then, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	node := &jqIf{cond: cond, then: then}
	t := p.next()
	switch {
	case t.kind == tkKeyword && t.val == "elif":
		els, err := p.parseIf()
		if err != nil {
			return nil, err
		}
		node.els = els
		return node, nil
	case t.kind == tkKeyword && t.val == "else":
		els, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		node.els = els
		if err := p.expect(tkKeyword, "end"); err != nil {
			return nil, err
		}
		return node, nil
	case t.kind == tkKeyword && t.val == "end":
		return node, nil
	}
	return nil, fmt.Errorf("unexpected token %q", t.val)
}

type jqObjEntry struct {
	key   jqNode
	value jqNode
}

func (p *jqParser) parseObject() (jqNode, error) {
	obj := &jqObjectCons{}
	if p.peek().kind == tkRBrace {
		p.next()
		return obj, nil
	}
	for {
		t := p.next()
		var key jqNode
		var value jqNode
		switch t.kind {
		case tkIdent, tkKeyword:
			key = &jqLiteral{val: t.val}
			value = &jqIndex{src: &jqIdentity{}, key: &jqLiteral{val: t.val}}
		case tkString:
			key = &jqLiteral{val: t.val}
			value = &jqIndex{src: &jqIdentity{}, key: &jqLiteral{val: t.val}}
		case tkVar:
			key = &jqLiteral{val: t.val}
			value = &jqVarRef{name: t.val}
		case tkLParen:
			k, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			if err := p.expect(tkRParen, ""); err != nil {
				return nil, err
			}
			key = k
		default:
			return nil, fmt.Errorf("unexpected token %q", t.val)
		}
		if p.peek().kind == tkColon {
			p.next()
			v, err := p.parseObjValue()
			if err != nil {
				return nil, err
			}
			value = v
		}
		obj.entries = append(obj.entries, jqObjEntry{key: key, value: value})
		if p.peek().kind == tkComma {
			p.next()
			continue
		}
		if err := p.expect(tkRBrace, ""); err != nil {
			return nil, err
		}
		return obj, nil
	}
}

func (p *jqParser) parseObjValue() (jqNode, error) {
	// object values: ExpD ('|' ExpD)* without comma
	left, err := p.parseAlt()
	if err != nil {
		return nil, err
	}
	for p.peek().kind == tkPipe {
		p.next()
		right, err := p.parseAlt()
		if err != nil {
			return nil, err
		}
		left = &jqPipe{left: left, right: right}
	}
	return left, nil
}

// ---- AST nodes ----

type jqIdentity struct{}

func (jqIdentity) eval(in interface{}, env *jqEnv) ([]interface{}, error) {
	return []interface{}{in}, nil
}

type jqRecurse struct{}

func (jqRecurse) eval(in interface{}, env *jqEnv) ([]interface{}, error) {
	var out []interface{}
	var walk func(v interface{})
	walk = func(v interface{}) {
		out = append(out, v)
		switch t := v.(type) {
		case []interface{}:
			for _, e := range t {
				walk(e)
			}
		case map[string]interface{}:
			for _, k := range sortedKeys(t) {
				walk(t[k])
			}
		}
	}
	walk(in)
	return out, nil
}

type jqLiteral struct{ val interface{} }

func (l *jqLiteral) eval(in interface{}, env *jqEnv) ([]interface{}, error) {
	return []interface{}{l.val}, nil
}

type jqVarRef struct{ name string }

func (v *jqVarRef) eval(in interface{}, env *jqEnv) ([]interface{}, error) {
	if v.name == "__loc__" {
		return []interface{}{map[string]interface{}{"file": "<stdin>", "line": jqNumber("1")}}, nil
	}
	if env.vars != nil {
		if val, ok := env.vars[v.name]; ok {
			return []interface{}{val}, nil
		}
	}
	return nil, fmt.Errorf("variable not defined: $%s", v.name)
}

type jqBind struct {
	src  jqNode
	name string
	body jqNode
}

func (b *jqBind) eval(in interface{}, env *jqEnv) ([]interface{}, error) {
	vals, err := b.src.eval(in, env)
	if err != nil {
		return nil, err
	}
	var out []interface{}
	for _, v := range vals {
		res, err := b.body.eval(in, env.with(b.name, v))
		if err != nil {
			return nil, err
		}
		out = append(out, res...)
	}
	return out, nil
}

type jqPipe struct{ left, right jqNode }

func (p *jqPipe) eval(in interface{}, env *jqEnv) ([]interface{}, error) {
	lefts, err := p.left.eval(in, env)
	if err != nil {
		return nil, err
	}
	var out []interface{}
	for _, l := range lefts {
		res, err := p.right.eval(l, env)
		if err != nil {
			return nil, err
		}
		out = append(out, res...)
	}
	return out, nil
}

type jqComma struct{ left, right jqNode }

func (c *jqComma) eval(in interface{}, env *jqEnv) ([]interface{}, error) {
	l, err := c.left.eval(in, env)
	if err != nil {
		return nil, err
	}
	r, err := c.right.eval(in, env)
	if err != nil {
		return nil, err
	}
	return append(l, r...), nil
}

type jqAlt struct{ left, right jqNode }

func (a *jqAlt) eval(in interface{}, env *jqEnv) ([]interface{}, error) {
	l, err := a.left.eval(in, env)
	var out []interface{}
	if err == nil {
		for _, v := range l {
			if jqTruthy(v) {
				out = append(out, v)
			}
		}
	}
	if len(out) > 0 {
		return out, nil
	}
	return a.right.eval(in, env)
}

type jqLogic struct {
	op          string
	left, right jqNode
}

func (l *jqLogic) eval(in interface{}, env *jqEnv) ([]interface{}, error) {
	lefts, err := l.left.eval(in, env)
	if err != nil {
		return nil, err
	}
	var out []interface{}
	for _, lv := range lefts {
		if l.op == "and" && !jqTruthy(lv) {
			out = append(out, false)
			continue
		}
		if l.op == "or" && jqTruthy(lv) {
			out = append(out, true)
			continue
		}
		rights, err := l.right.eval(in, env)
		if err != nil {
			return nil, err
		}
		for _, rv := range rights {
			out = append(out, jqTruthy(rv))
		}
	}
	return out, nil
}

type jqNeg struct{ operand jqNode }

func (n *jqNeg) eval(in interface{}, env *jqEnv) ([]interface{}, error) {
	vals, err := n.operand.eval(in, env)
	if err != nil {
		return nil, err
	}
	out := make([]interface{}, 0, len(vals))
	for _, v := range vals {
		f, ok := toFloat(v)
		if !ok {
			return nil, fmt.Errorf("%s (%s) cannot be negated", jqTypeName(v), jqPreview(v))
		}
		out = append(out, numberValue(-f))
	}
	return out, nil
}

type jqBinOp struct {
	op          string
	left, right jqNode
}

func (b *jqBinOp) eval(in interface{}, env *jqEnv) ([]interface{}, error) {
	rights, err := b.right.eval(in, env)
	if err != nil {
		return nil, err
	}
	lefts, err := b.left.eval(in, env)
	if err != nil {
		return nil, err
	}
	var out []interface{}
	for _, r := range rights {
		for _, l := range lefts {
			v, err := jqApplyOp(b.op, l, r)
			if err != nil {
				return nil, err
			}
			out = append(out, v)
		}
	}
	return out, nil
}

func jqApplyOp(op string, l, r interface{}) (interface{}, error) {
	switch op {
	case "==":
		return jqCompare(l, r) == 0, nil
	case "!=":
		return jqCompare(l, r) != 0, nil
	case "<":
		return jqCompare(l, r) < 0, nil
	case "<=":
		return jqCompare(l, r) <= 0, nil
	case ">":
		return jqCompare(l, r) > 0, nil
	case ">=":
		return jqCompare(l, r) >= 0, nil
	case "+":
		if l == nil {
			return r, nil
		}
		if r == nil {
			return l, nil
		}
		if lf, ok := toFloat(l); ok {
			if rf, ok := toFloat(r); ok {
				return numberValue(lf + rf), nil
			}
		}
		if ls, ok := l.(string); ok {
			if rs, ok := r.(string); ok {
				return ls + rs, nil
			}
		}
		if la, ok := l.([]interface{}); ok {
			if ra, ok := r.([]interface{}); ok {
				out := make([]interface{}, 0, len(la)+len(ra))
				out = append(out, la...)
				out = append(out, ra...)
				return out, nil
			}
		}
		if lm, ok := l.(map[string]interface{}); ok {
			if rm, ok := r.(map[string]interface{}); ok {
				out := make(map[string]interface{}, len(lm)+len(rm))
				for k, v := range lm {
					out[k] = v
				}
				for k, v := range rm {
					out[k] = v
				}
				return out, nil
			}
		}
		return nil, fmt.Errorf("%s (%s) and %s (%s) cannot be added", jqTypeName(l), jqPreview(l), jqTypeName(r), jqPreview(r))
	case "-":
		if lf, ok := toFloat(l); ok {
			if rf, ok := toFloat(r); ok {
				return numberValue(lf - rf), nil
			}
		}
		if la, ok := l.([]interface{}); ok {
			if ra, ok := r.([]interface{}); ok {
				out := []interface{}{}
				for _, e := range la {
					found := false
					for _, x := range ra {
						if jqCompare(e, x) == 0 {
							found = true
							break
						}
					}
					if !found {
						out = append(out, e)
					}
				}
				return out, nil
			}
		}
		return nil, fmt.Errorf("%s (%s) and %s (%s) cannot be subtracted", jqTypeName(l), jqPreview(l), jqTypeName(r), jqPreview(r))
	case "*":
		if lf, ok := toFloat(l); ok {
			if rf, ok := toFloat(r); ok {
				return numberValue(lf * rf), nil
			}
		}
		if ls, ok := l.(string); ok {
			if rf, ok := toFloat(r); ok {
				if rf <= 0 {
					return nil, nil
				}
				return strings.Repeat(ls, int(rf)), nil
			}
		}
		return nil, fmt.Errorf("%s (%s) and %s (%s) cannot be multiplied", jqTypeName(l), jqPreview(l), jqTypeName(r), jqPreview(r))
	case "/":
		if lf, ok := toFloat(l); ok {
			if rf, ok := toFloat(r); ok {
				if rf == 0 {
					return nil, fmt.Errorf("%s (%s) and %s (%s) cannot be divided because the divisor is zero", jqTypeName(l), jqPreview(l), jqTypeName(r), jqPreview(r))
				}
				return numberValue(lf / rf), nil
			}
		}
		if ls, ok := l.(string); ok {
			if rs, ok := r.(string); ok {
				parts := strings.Split(ls, rs)
				out := make([]interface{}, len(parts))
				for i, p := range parts {
					out[i] = p
				}
				return out, nil
			}
		}
		return nil, fmt.Errorf("%s (%s) and %s (%s) cannot be divided", jqTypeName(l), jqPreview(l), jqTypeName(r), jqPreview(r))
	case "%":
		if lf, ok := toFloat(l); ok {
			if rf, ok := toFloat(r); ok {
				if int64(rf) == 0 {
					return nil, fmt.Errorf("%s (%s) and %s (%s) cannot be divided because the divisor is zero", jqTypeName(l), jqPreview(l), jqTypeName(r), jqPreview(r))
				}
				return numberValue(float64(int64(lf) % int64(rf))), nil
			}
		}
		return nil, fmt.Errorf("%s (%s) and %s (%s) cannot be divided", jqTypeName(l), jqPreview(l), jqTypeName(r), jqPreview(r))
	}
	return nil, fmt.Errorf("unknown operator %s", op)
}

type jqIndex struct {
	src jqNode
	key jqNode
}

func (ix *jqIndex) eval(in interface{}, env *jqEnv) ([]interface{}, error) {
	srcs, err := ix.src.eval(in, env)
	if err != nil {
		return nil, err
	}
	keys, err := ix.key.eval(in, env)
	if err != nil {
		return nil, err
	}
	var out []interface{}
	for _, s := range srcs {
		for _, k := range keys {
			v, err := jqIndexValue(s, k)
			if err != nil {
				return nil, err
			}
			out = append(out, v)
		}
	}
	return out, nil
}

func jqIndexValue(s interface{}, k interface{}) (interface{}, error) {
	switch key := k.(type) {
	case string:
		switch t := s.(type) {
		case nil:
			return nil, nil
		case map[string]interface{}:
			return t[key], nil
		default:
			return nil, fmt.Errorf("expected an object but got: %s (%s)", jqTypeName(s), jqPreview(s))
		}
	default:
		if f, ok := toFloat(k); ok {
			switch t := s.(type) {
			case nil:
				return nil, nil
			case []interface{}:
				i := int(math.Floor(f))
				if i < 0 {
					i += len(t)
				}
				if i < 0 || i >= len(t) {
					return nil, nil
				}
				return t[i], nil
			default:
				return nil, fmt.Errorf("expected an array but got: %s (%s)", jqTypeName(s), jqPreview(s))
			}
		}
		if arr, ok := k.([]interface{}); ok {
			if t, ok := s.([]interface{}); ok {
				out := []interface{}{}
				for i := 0; i+len(arr) <= len(t); i++ {
					match := true
					for j, e := range arr {
						if jqCompare(t[i+j], e) != 0 {
							match = false
							break
						}
					}
					if match {
						out = append(out, jqNumber(strconv.Itoa(i)))
					}
				}
				return out, nil
			}
		}
		return nil, fmt.Errorf("expected an object but got: %s (%s)", jqTypeName(s), jqPreview(s))
	}
}

type jqSlice struct {
	src, from, to jqNode
}

func (sl *jqSlice) eval(in interface{}, env *jqEnv) ([]interface{}, error) {
	srcs, err := sl.src.eval(in, env)
	if err != nil {
		return nil, err
	}
	var out []interface{}
	for _, s := range srcs {
		from := 0
		to := math.MaxInt32
		if sl.from != nil {
			fv, err := sl.from.eval(in, env)
			if err != nil {
				return nil, err
			}
			if len(fv) > 0 {
				if f, ok := toFloat(fv[0]); ok {
					from = int(math.Floor(f))
				}
			}
		}
		if sl.to != nil {
			tv, err := sl.to.eval(in, env)
			if err != nil {
				return nil, err
			}
			if len(tv) > 0 {
				if f, ok := toFloat(tv[0]); ok {
					to = int(math.Ceil(f))
				}
			}
		}
		switch t := s.(type) {
		case nil:
			out = append(out, nil)
		case []interface{}:
			f, e := clampSlice(from, to, len(t))
			out = append(out, append([]interface{}{}, t[f:e]...))
		case string:
			rs := []rune(t)
			f, e := clampSlice(from, to, len(rs))
			out = append(out, string(rs[f:e]))
		default:
			return nil, fmt.Errorf("expected an array but got: %s (%s)", jqTypeName(s), jqPreview(s))
		}
	}
	return out, nil
}

func clampSlice(from, to, n int) (int, int) {
	if from < 0 {
		from += n
	}
	if to < 0 {
		to += n
	}
	if from < 0 {
		from = 0
	}
	if to > n {
		to = n
	}
	if from > n {
		from = n
	}
	if to < from {
		to = from
	}
	return from, to
}

type jqIterate struct{ src jqNode }

func (it *jqIterate) eval(in interface{}, env *jqEnv) ([]interface{}, error) {
	srcs, err := it.src.eval(in, env)
	if err != nil {
		return nil, err
	}
	var out []interface{}
	for _, s := range srcs {
		switch t := s.(type) {
		case []interface{}:
			out = append(out, t...)
		case map[string]interface{}:
			for _, k := range sortedKeys(t) {
				out = append(out, t[k])
			}
		default:
			return nil, fmt.Errorf("cannot iterate over: %s (%s)", jqTypeName(s), jqPreview(s))
		}
	}
	return out, nil
}

type jqTry struct {
	body  jqNode
	catch jqNode
}

func (t *jqTry) eval(in interface{}, env *jqEnv) ([]interface{}, error) {
	out, err := t.body.eval(in, env)
	if err != nil {
		if t.catch != nil {
			return t.catch.eval(err.Error(), env)
		}
		return nil, nil
	}
	return out, nil
}

type jqIf struct {
	cond, then, els jqNode
}

func (n *jqIf) eval(in interface{}, env *jqEnv) ([]interface{}, error) {
	conds, err := n.cond.eval(in, env)
	if err != nil {
		return nil, err
	}
	var out []interface{}
	for _, c := range conds {
		if jqTruthy(c) {
			res, err := n.then.eval(in, env)
			if err != nil {
				return nil, err
			}
			out = append(out, res...)
		} else if n.els != nil {
			res, err := n.els.eval(in, env)
			if err != nil {
				return nil, err
			}
			out = append(out, res...)
		} else {
			out = append(out, in)
		}
	}
	return out, nil
}

type jqReduce struct {
	src          jqNode
	name         string
	init, update jqNode
}

func (r *jqReduce) eval(in interface{}, env *jqEnv) ([]interface{}, error) {
	inits, err := r.init.eval(in, env)
	if err != nil {
		return nil, err
	}
	srcs, err := r.src.eval(in, env)
	if err != nil {
		return nil, err
	}
	var out []interface{}
	for _, acc := range inits {
		cur := acc
		for _, s := range srcs {
			res, err := r.update.eval(cur, env.with(r.name, s))
			if err != nil {
				return nil, err
			}
			if len(res) == 0 {
				cur = nil
			} else {
				cur = res[len(res)-1]
			}
		}
		out = append(out, cur)
	}
	return out, nil
}

type jqArrayCons struct{ body jqNode }

func (a *jqArrayCons) eval(in interface{}, env *jqEnv) ([]interface{}, error) {
	if a.body == nil {
		return []interface{}{[]interface{}{}}, nil
	}
	vals, err := a.body.eval(in, env)
	if err != nil {
		return nil, err
	}
	if vals == nil {
		vals = []interface{}{}
	}
	return []interface{}{vals}, nil
}

type jqObjectCons struct{ entries []jqObjEntry }

func (o *jqObjectCons) eval(in interface{}, env *jqEnv) ([]interface{}, error) {
	results := []map[string]interface{}{{}}
	for _, e := range o.entries {
		keys, err := e.key.eval(in, env)
		if err != nil {
			return nil, err
		}
		vals, err := e.value.eval(in, env)
		if err != nil {
			return nil, err
		}
		var next []map[string]interface{}
		for _, base := range results {
			for _, k := range keys {
				ks, ok := k.(string)
				if !ok {
					return nil, fmt.Errorf("expected a string for object key but got: %s (%s)", jqTypeName(k), jqPreview(k))
				}
				for _, v := range vals {
					m := make(map[string]interface{}, len(base)+1)
					for bk, bv := range base {
						m[bk] = bv
					}
					m[ks] = v
					next = append(next, m)
				}
			}
		}
		results = next
	}
	out := make([]interface{}, len(results))
	for i, m := range results {
		out[i] = m
	}
	return out, nil
}

type jqFuncCall struct {
	name string
	args []jqNode
}

func (f *jqFuncCall) eval(in interface{}, env *jqEnv) ([]interface{}, error) {
	fn := jqFuncs[f.name]
	return fn(in, f.args, env)
}

// ---- helpers ----

func jqTruthy(v interface{}) bool {
	switch t := v.(type) {
	case nil:
		return false
	case bool:
		return t
	}
	return true
}

func jqTypeName(v interface{}) string {
	switch v.(type) {
	case nil:
		return "null"
	case bool:
		return "boolean"
	case jqNumber, float64, int, int64:
		return "number"
	case string:
		return "string"
	case []interface{}:
		return "array"
	case map[string]interface{}:
		return "object"
	}
	return "unknown"
}

func jqPreview(v interface{}) string {
	b, err := json.Marshal(v)
	if err != nil {
		return fmt.Sprint(v)
	}
	s := string(b)
	if len(s) > 30 {
		s = s[:27] + "..."
	}
	return s
}

func jqTypeOrder(v interface{}) int {
	switch v.(type) {
	case nil:
		return 0
	case bool:
		if v.(bool) {
			return 2
		}
		return 1
	case jqNumber, float64, int, int64:
		return 3
	case string:
		return 4
	case []interface{}:
		return 5
	case map[string]interface{}:
		return 6
	}
	return 7
}

func jqCompare(a, b interface{}) int {
	ta, tb := jqTypeOrder(a), jqTypeOrder(b)
	if ta != tb {
		if ta < tb {
			return -1
		}
		return 1
	}
	switch ta {
	case 3:
		fa, _ := toFloat(a)
		fb, _ := toFloat(b)
		switch {
		case fa < fb:
			return -1
		case fa > fb:
			return 1
		}
		return 0
	case 4:
		return strings.Compare(a.(string), b.(string))
	case 5:
		aa, ba := a.([]interface{}), b.([]interface{})
		for i := 0; i < len(aa) && i < len(ba); i++ {
			if c := jqCompare(aa[i], ba[i]); c != 0 {
				return c
			}
		}
		return len(aa) - len(ba)
	case 6:
		am, bm := a.(map[string]interface{}), b.(map[string]interface{})
		ak, bk := sortedKeys(am), sortedKeys(bm)
		for i := 0; i < len(ak) && i < len(bk); i++ {
			if c := strings.Compare(ak[i], bk[i]); c != 0 {
				return c
			}
		}
		if len(ak) != len(bk) {
			return len(ak) - len(bk)
		}
		for _, k := range ak {
			if c := jqCompare(am[k], bm[k]); c != 0 {
				return c
			}
		}
		return 0
	}
	return 0
}

func sortedKeys(m map[string]interface{}) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

type jqFunc func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error)

var jqFuncs map[string]jqFunc

func init() {
	jqFuncs = map[string]jqFunc{
		"empty": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			return nil, nil
		},
		"not": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			return []interface{}{!jqTruthy(in)}, nil
		},
		"length": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			switch t := in.(type) {
			case nil:
				return []interface{}{jqNumber("0")}, nil
			case bool:
				return nil, fmt.Errorf("boolean (%s) has no length", jqPreview(in))
			case string:
				return []interface{}{jqNumber(strconv.Itoa(len([]rune(t))))}, nil
			case []interface{}:
				return []interface{}{jqNumber(strconv.Itoa(len(t)))}, nil
			case map[string]interface{}:
				return []interface{}{jqNumber(strconv.Itoa(len(t)))}, nil
			default:
				f, _ := toFloat(in)
				return []interface{}{numberValue(math.Abs(f))}, nil
			}
		},
		"keys": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			switch t := in.(type) {
			case map[string]interface{}:
				keys := sortedKeys(t)
				out := make([]interface{}, len(keys))
				for i, k := range keys {
					out[i] = k
				}
				return []interface{}{out}, nil
			case []interface{}:
				out := make([]interface{}, len(t))
				for i := range t {
					out[i] = jqNumber(strconv.Itoa(i))
				}
				return []interface{}{out}, nil
			}
			return nil, fmt.Errorf("%s (%s) has no keys", jqTypeName(in), jqPreview(in))
		},
		"values": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			if in == nil {
				return nil, nil
			}
			return []interface{}{in}, nil
		},
		"type": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			return []interface{}{jqTypeName(in)}, nil
		},
		"tostring": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			if s, ok := in.(string); ok {
				return []interface{}{s}, nil
			}
			b, _ := json.Marshal(in)
			return []interface{}{string(b)}, nil
		},
		"tojson": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			b, _ := json.Marshal(in)
			return []interface{}{string(b)}, nil
		},
		"fromjson": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			s, ok := in.(string)
			if !ok {
				return nil, fmt.Errorf("%s (%s) cannot be parsed as JSON", jqTypeName(in), jqPreview(in))
			}
			var v interface{}
			d := json.NewDecoder(strings.NewReader(s))
			d.UseNumber()
			if err := d.Decode(&v); err != nil {
				return nil, fmt.Errorf("%s (%s) cannot be parsed as JSON", jqTypeName(in), jqPreview(in))
			}
			return []interface{}{normalizeJSON(v)}, nil
		},
		"tonumber": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			switch t := in.(type) {
			case string:
				f, err := strconv.ParseFloat(strings.TrimSpace(t), 64)
				if err != nil {
					return nil, fmt.Errorf("%s (%s) cannot be parsed as a number", jqTypeName(in), jqPreview(in))
				}
				return []interface{}{numberValue(f)}, nil
			default:
				if _, ok := toFloat(in); ok {
					return []interface{}{in}, nil
				}
			}
			return nil, fmt.Errorf("%s (%s) cannot be parsed as a number", jqTypeName(in), jqPreview(in))
		},
		"add": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			var items []interface{}
			switch t := in.(type) {
			case []interface{}:
				items = t
			case map[string]interface{}:
				for _, k := range sortedKeys(t) {
					items = append(items, t[k])
				}
			default:
				return nil, fmt.Errorf("cannot iterate over: %s (%s)", jqTypeName(in), jqPreview(in))
			}
			var acc interface{}
			for i, it := range items {
				if i == 0 {
					acc = it
					continue
				}
				v, err := jqApplyOp("+", acc, it)
				if err != nil {
					return nil, err
				}
				acc = v
			}
			return []interface{}{acc}, nil
		},
		"first": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			if len(args) == 1 {
				vals, err := args[0].eval(in, env)
				if err != nil {
					return nil, err
				}
				if len(vals) == 0 {
					return nil, nil
				}
				return vals[:1], nil
			}
			if t, ok := in.([]interface{}); ok {
				if len(t) == 0 {
					return []interface{}{nil}, nil
				}
				return []interface{}{t[0]}, nil
			}
			return nil, fmt.Errorf("expected an array but got: %s (%s)", jqTypeName(in), jqPreview(in))
		},
		"last": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			if len(args) == 1 {
				vals, err := args[0].eval(in, env)
				if err != nil {
					return nil, err
				}
				if len(vals) == 0 {
					return nil, nil
				}
				return vals[len(vals)-1:], nil
			}
			if t, ok := in.([]interface{}); ok {
				if len(t) == 0 {
					return []interface{}{nil}, nil
				}
				return []interface{}{t[len(t)-1]}, nil
			}
			return nil, fmt.Errorf("expected an array but got: %s (%s)", jqTypeName(in), jqPreview(in))
		},
		"reverse": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			switch t := in.(type) {
			case nil:
				return []interface{}{[]interface{}{}}, nil
			case []interface{}:
				out := make([]interface{}, len(t))
				for i, v := range t {
					out[len(t)-1-i] = v
				}
				return []interface{}{out}, nil
			case string:
				rs := []rune(t)
				for i, j := 0, len(rs)-1; i < j; i, j = i+1, j-1 {
					rs[i], rs[j] = rs[j], rs[i]
				}
				return []interface{}{string(rs)}, nil
			}
			return nil, fmt.Errorf("cannot reverse: %s (%s)", jqTypeName(in), jqPreview(in))
		},
		"sort": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			t, ok := in.([]interface{})
			if !ok {
				return nil, fmt.Errorf("%s (%s) cannot be sorted, as it is not an array", jqTypeName(in), jqPreview(in))
			}
			out := append([]interface{}{}, t...)
			sort.SliceStable(out, func(i, j int) bool { return jqCompare(out[i], out[j]) < 0 })
			return []interface{}{out}, nil
		},
		"sort_by": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			t, ok := in.([]interface{})
			if !ok {
				return nil, fmt.Errorf("%s (%s) cannot be sorted, as it is not an array", jqTypeName(in), jqPreview(in))
			}
			keys := make([]interface{}, len(t))
			for i, v := range t {
				kv, err := args[0].eval(v, env)
				if err != nil {
					return nil, err
				}
				keys[i] = kv
			}
			idx := make([]int, len(t))
			for i := range idx {
				idx[i] = i
			}
			sort.SliceStable(idx, func(i, j int) bool { return jqCompare(keys[idx[i]], keys[idx[j]]) < 0 })
			out := make([]interface{}, len(t))
			for i, k := range idx {
				out[i] = t[k]
			}
			return []interface{}{out}, nil
		},
		"group_by": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			t, ok := in.([]interface{})
			if !ok {
				return nil, fmt.Errorf("%s (%s) cannot be grouped, as it is not an array", jqTypeName(in), jqPreview(in))
			}
			keys := make([]interface{}, len(t))
			for i, v := range t {
				kv, err := args[0].eval(v, env)
				if err != nil {
					return nil, err
				}
				keys[i] = kv
			}
			idx := make([]int, len(t))
			for i := range idx {
				idx[i] = i
			}
			sort.SliceStable(idx, func(i, j int) bool { return jqCompare(keys[idx[i]], keys[idx[j]]) < 0 })
			out := []interface{}{}
			var cur []interface{}
			var curKey interface{}
			for n, k := range idx {
				if n == 0 || jqCompare(keys[k], curKey) != 0 {
					if cur != nil {
						out = append(out, cur)
					}
					cur = []interface{}{}
					curKey = keys[k]
				}
				cur = append(cur, t[k])
			}
			if cur != nil {
				out = append(out, cur)
			}
			return []interface{}{out}, nil
		},
		"unique": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			t, ok := in.([]interface{})
			if !ok {
				return nil, fmt.Errorf("%s (%s) cannot be sorted, as it is not an array", jqTypeName(in), jqPreview(in))
			}
			out := append([]interface{}{}, t...)
			sort.SliceStable(out, func(i, j int) bool { return jqCompare(out[i], out[j]) < 0 })
			res := []interface{}{}
			for i, v := range out {
				if i == 0 || jqCompare(v, out[i-1]) != 0 {
					res = append(res, v)
				}
			}
			return []interface{}{res}, nil
		},
		"min": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			t, ok := in.([]interface{})
			if !ok {
				return nil, fmt.Errorf("expected an array but got: %s (%s)", jqTypeName(in), jqPreview(in))
			}
			if len(t) == 0 {
				return []interface{}{nil}, nil
			}
			m := t[0]
			for _, v := range t[1:] {
				if jqCompare(v, m) < 0 {
					m = v
				}
			}
			return []interface{}{m}, nil
		},
		"max": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			t, ok := in.([]interface{})
			if !ok {
				return nil, fmt.Errorf("expected an array but got: %s (%s)", jqTypeName(in), jqPreview(in))
			}
			if len(t) == 0 {
				return []interface{}{nil}, nil
			}
			m := t[0]
			for _, v := range t[1:] {
				if jqCompare(v, m) >= 0 {
					m = v
				}
			}
			return []interface{}{m}, nil
		},
		"map": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			it := &jqIterate{src: &jqIdentity{}}
			items, err := it.eval(in, env)
			if err != nil {
				return nil, err
			}
			out := []interface{}{}
			for _, v := range items {
				res, err := args[0].eval(v, env)
				if err != nil {
					return nil, err
				}
				out = append(out, res...)
			}
			return []interface{}{out}, nil
		},
		"map_values": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			switch t := in.(type) {
			case map[string]interface{}:
				out := map[string]interface{}{}
				for k, v := range t {
					res, err := args[0].eval(v, env)
					if err != nil {
						return nil, err
					}
					if len(res) > 0 {
						out[k] = res[0]
					}
				}
				return []interface{}{out}, nil
			case []interface{}:
				out := []interface{}{}
				for _, v := range t {
					res, err := args[0].eval(v, env)
					if err != nil {
						return nil, err
					}
					if len(res) > 0 {
						out = append(out, res[0])
					}
				}
				return []interface{}{out}, nil
			}
			return nil, fmt.Errorf("cannot iterate over: %s (%s)", jqTypeName(in), jqPreview(in))
		},
		"select": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			conds, err := args[0].eval(in, env)
			if err != nil {
				return nil, err
			}
			var out []interface{}
			for _, c := range conds {
				if jqTruthy(c) {
					out = append(out, in)
				}
			}
			return out, nil
		},
		"recurse": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			return jqRecurse{}.eval(in, env)
		},
		"has": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			keys, err := args[0].eval(in, env)
			if err != nil {
				return nil, err
			}
			var out []interface{}
			for _, k := range keys {
				switch t := in.(type) {
				case map[string]interface{}:
					ks, ok := k.(string)
					if !ok {
						return nil, fmt.Errorf("cannot check whether object has a key: %s (%s)", jqTypeName(k), jqPreview(k))
					}
					_, exists := t[ks]
					out = append(out, exists)
				case []interface{}:
					f, ok := toFloat(k)
					if !ok {
						return nil, fmt.Errorf("cannot check whether array has a key: %s (%s)", jqTypeName(k), jqPreview(k))
					}
					out = append(out, f >= 0 && int(f) < len(t))
				default:
					return nil, fmt.Errorf("cannot check whether %s has a key", jqTypeName(in))
				}
			}
			return out, nil
		},
		"to_entries": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			t, ok := in.(map[string]interface{})
			if !ok {
				return nil, fmt.Errorf("%s (%s) has no keys", jqTypeName(in), jqPreview(in))
			}
			out := []interface{}{}
			for _, k := range sortedKeys(t) {
				out = append(out, map[string]interface{}{"key": k, "value": t[k]})
			}
			return []interface{}{out}, nil
		},
		"from_entries": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			t, ok := in.([]interface{})
			if !ok {
				return nil, fmt.Errorf("cannot iterate over: %s (%s)", jqTypeName(in), jqPreview(in))
			}
			out := map[string]interface{}{}
			for _, e := range t {
				m, ok := e.(map[string]interface{})
				if !ok {
					return nil, fmt.Errorf("expected an object but got: %s (%s)", jqTypeName(e), jqPreview(e))
				}
				var key interface{}
				for _, kn := range []string{"key", "k", "name", "Name", "Key", "K"} {
					if v, ok := m[kn]; ok && v != nil {
						key = v
						break
					}
				}
				var val interface{}
				for _, vn := range []string{"value", "v", "Value", "V"} {
					if v, ok := m[vn]; ok {
						val = v
						break
					}
				}
				ks := ""
				switch kt := key.(type) {
				case string:
					ks = kt
				case nil:
					ks = "null"
				default:
					b, _ := json.Marshal(kt)
					ks = string(b)
				}
				out[ks] = val
			}
			return []interface{}{out}, nil
		},
		"with_entries": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			te, err := jqFuncs["to_entries"](in, nil, env)
			if err != nil {
				return nil, err
			}
			mapped, err := jqFuncs["map"](te[0], args, env)
			if err != nil {
				return nil, err
			}
			return jqFuncs["from_entries"](mapped[0], nil, env)
		},
		"flatten": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			t, ok := in.([]interface{})
			if !ok {
				return nil, fmt.Errorf("cannot iterate over: %s (%s)", jqTypeName(in), jqPreview(in))
			}
			depth := math.MaxInt32
			if len(args) == 1 {
				dv, err := args[0].eval(in, env)
				if err != nil {
					return nil, err
				}
				if len(dv) > 0 {
					if f, ok := toFloat(dv[0]); ok {
						depth = int(f)
					}
				}
			}
			var flat func(a []interface{}, d int) []interface{}
			flat = func(a []interface{}, d int) []interface{} {
				out := []interface{}{}
				for _, v := range a {
					if sub, ok := v.([]interface{}); ok && d > 0 {
						out = append(out, flat(sub, d-1)...)
					} else {
						out = append(out, v)
					}
				}
				return out
			}
			return []interface{}{flat(t, depth)}, nil
		},
		"range": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			var from, to, step float64 = 0, 0, 1
			vals := make([][]interface{}, len(args))
			for i, a := range args {
				v, err := a.eval(in, env)
				if err != nil {
					return nil, err
				}
				vals[i] = v
			}
			var out []interface{}
			var gen func(i int, acc []float64)
			gen = func(i int, acc []float64) {
				if i == len(vals) {
					switch len(acc) {
					case 1:
						to = acc[0]
					case 2:
						from, to = acc[0], acc[1]
					case 3:
						from, to, step = acc[0], acc[1], acc[2]
					}
					if step > 0 {
						for x := from; x < to; x += step {
							out = append(out, numberValue(x))
						}
					} else if step < 0 {
						for x := from; x > to; x += step {
							out = append(out, numberValue(x))
						}
					}
					return
				}
				for _, v := range vals[i] {
					f, _ := toFloat(v)
					gen(i+1, append(acc, f))
				}
			}
			gen(0, nil)
			return out, nil
		},
		"floor": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			return jqMath(in, math.Floor)
		},
		"ceil": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			return jqMath(in, math.Ceil)
		},
		"round": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			return jqMath(in, math.Round)
		},
		"sqrt": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			return jqMath(in, math.Sqrt)
		},
		"fabs": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			return jqMath(in, math.Abs)
		},
		"abs": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			return jqMath(in, math.Abs)
		},
		"ascii_downcase": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			s, ok := in.(string)
			if !ok {
				return nil, fmt.Errorf("%s (%s) cannot be lowercased", jqTypeName(in), jqPreview(in))
			}
			return []interface{}{strings.Map(func(r rune) rune {
				if r >= 'A' && r <= 'Z' {
					return r + 32
				}
				return r
			}, s)}, nil
