		"ascii_upcase": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			s, ok := in.(string)
			if !ok {
				return nil, fmt.Errorf("%s (%s) cannot be uppercased", jqTypeName(in), jqPreview(in))
			}
			return []interface{}{strings.Map(func(r rune) rune {
				if r >= 'a' && r <= 'z' {
					return r - 32
				}
				return r
			}, s)}, nil
		},
		"split": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			s, ok := in.(string)
			if !ok {
				return nil, fmt.Errorf("%s (%s) cannot be split", jqTypeName(in), jqPreview(in))
			}
			seps, err := args[0].eval(in, env)
			if err != nil {
				return nil, err
			}
			var out []interface{}
			for _, sep := range seps {
				ss, _ := sep.(string)
				parts := strings.Split(s, ss)
				arr := make([]interface{}, len(parts))
				for i, p := range parts {
					arr[i] = p
				}
				out = append(out, arr)
			}
			return out, nil
		},
		"join": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			t, ok := in.([]interface{})
			if !ok {
				return nil, fmt.Errorf("cannot iterate over: %s (%s)", jqTypeName(in), jqPreview(in))
			}
			seps, err := args[0].eval(in, env)
			if err != nil {
				return nil, err
			}
			var out []interface{}
			for _, sep := range seps {
				ss, _ := sep.(string)
				parts := make([]string, len(t))
				for i, v := range t {
					switch vt := v.(type) {
					case nil:
						parts[i] = ""
					case string:
						parts[i] = vt
					case bool, jqNumber:
						b, _ := json.Marshal(vt)
						parts[i] = string(b)
					default:
						return nil, fmt.Errorf("cannot join with %s", jqTypeName(v))
