			for _, v := range vals {
				out = append(out, jqContains(in, v))
			}
			return out, nil
		},
		"any": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			t, ok := in.([]interface{})
			if !ok {
				return nil, fmt.Errorf("cannot iterate over: %s (%s)", jqTypeName(in), jqPreview(in))
			}
			for _, v := range t {
				if len(args) == 1 {
					res, err := args[0].eval(v, env)
					if err != nil {
						return nil, err
					}
					for _, r := range res {
						if jqTruthy(r) {
							return []interface{}{true}, nil
						}
					}
				} else if jqTruthy(v) {
					return []interface{}{true}, nil
				}
			}
			return []interface{}{false}, nil
		},
		"all": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			t, ok := in.([]interface{})
			if !ok {
				return nil, fmt.Errorf("cannot iterate over: %s (%s)", jqTypeName(in), jqPreview(in))
			}
			for _, v := range t {
				if len(args) == 1 {
					res, err := args[0].eval(v, env)
					if err != nil {
						return nil, err
					}
					for _, r := range res {
						if !jqTruthy(r) {
							return []interface{}{false}, nil
						}
					}
				} else if !jqTruthy(v) {
					return []interface{}{false}, nil
				}
			}
			return []interface{}{true}, nil
		},
		"keys_unsorted": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			return jqFuncs["keys"](in, args, env)
