		"del": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			ix, ok := args[0].(*jqIndex)
			if !ok {
				return nil, fmt.Errorf("invalid path expression")
			}
			keys, err := ix.key.eval(in, env)
			if err != nil {
				return nil, err
			}
			switch t := in.(type) {
			case map[string]interface{}:
				out := make(map[string]interface{}, len(t))
				for k, v := range t {
					out[k] = v
				}
				for _, k := range keys {
					if ks, ok := k.(string); ok {
						delete(out, ks)
					}
				}
				return []interface{}{out}, nil
			case []interface{}:
				del := map[int]bool{}
				for _, k := range keys {
					if f, ok := toFloat(k); ok {
						i := int(f)
						if i < 0 {
							i += len(t)
						}
						del[i] = true
					}
				}
				out := []interface{}{}
				for i, v := range t {
					if !del[i] {
						out = append(out, v)
					}
				}
				return []interface{}{out}, nil
			case nil:
				return []interface{}{nil}, nil
			}
			return nil, fmt.Errorf("cannot delete field of %s", jqTypeName(in))
		},
		"env": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			return []interface{}{map[string]interface{}{}}, nil
		},
		"tostream": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			return []interface{}{in}, nil
		},
		"ascii": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			f, ok := toFloat(in)
			if !ok {
