			return []interface{}{string(rune(int(f)))}, nil
		},
		"explode": func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
			s, ok := in.(string)
			if !ok {
				return nil, fmt.Errorf("%s (%s) cannot be exploded", jqTypeName(in), jqPreview(in))
