			}
			return []interface{}{strings.TrimRightFunc(s, unicode.IsSpace)}, nil
		},
		"tostring_or_null": nil,
	}
	delete(jqFuncs, "tostring_or_null")
	jqFuncs["objects"] = jqTypeFilter("object")
	jqFuncs["arrays"] = jqTypeFilter("array")
	jqFuncs["strings"] = jqTypeFilter("string")
	jqFuncs["numbers"] = jqTypeFilter("number")
	jqFuncs["booleans"] = jqTypeFilter("boolean")
	jqFuncs["nulls"] = jqTypeFilter("null")
	jqFuncs["iterables"] = func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
		switch in.(type) {
		case []interface{}, map[string]interface{}:
			return []interface{}{in}, nil
		}
		return nil, nil
	}
	jqFuncs["scalars"] = func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
		switch in.(type) {
		case []interface{}, map[string]interface{}:
			return nil, nil
		}
		return []interface{}{in}, nil
	}
}

func jqTypeFilter(name string) jqFunc {
	return func(in interface{}, args []jqNode, env *jqEnv) ([]interface{}, error) {
		if jqTypeName(in) == name {
			return []interface{}{in}, nil
		}
		return nil, nil
	}
}

func jqMath(in interface{}, f func(float64) float64) ([]interface{}, error) {
	v, ok := toFloat(in)
	if !ok {
		return nil, fmt.Errorf("%s (%s) number required", jqTypeName(in), jqPreview(in))
	}
	return []interface{}{numberValue(f(v))}, nil
}

func jqStrPred(in interface{}, args []jqNode, env *jqEnv, pred func(string, string) bool, name string) ([]interface{}, error) {
	s, ok := in.(string)
	if !ok {
		return nil, fmt.Errorf("%s() cannot be applied to: %s (%s)", name, jqTypeName(in), jqPreview(in))
	}
	vals, err := args[0].eval(in, env)
	if err != nil {
		return nil, err
	}
	var out []interface{}
	for _, v := range vals {
		vs, ok := v.(string)
		if !ok {
			return nil, fmt.Errorf("%s() cannot be applied to: %s (%s)", name, jqTypeName(v), jqPreview(v))
		}
		out = append(out, pred(s, vs))
	}
	return out, nil
}

func jqStrTrim(in interface{}, args []jqNode, env *jqEnv, f func(string, string) string) ([]interface{}, error) {
	s, ok := in.(string)
	if !ok {
		return []interface{}{in}, nil
	}
	vals, err := args[0].eval(in, env)
	if err != nil {
		return nil, err
	}
	var out []interface{}
	for _, v := range vals {
		vs, ok := v.(string)
		if !ok {
			out = append(out, s)
			continue
		}
		out = append(out, f(s, vs))
	}
	return out, nil
}

func jqContains(a, b interface{}) bool {
	switch bt := b.(type) {
	case map[string]interface{}:
		am, ok := a.(map[string]interface{})
		if !ok {
			return false
		}
		for k, bv := range bt {
			av, ok := am[k]
			if !ok || !jqContains(av, bv) {
				return false
			}
		}
		return true
	case []interface{}:
		aa, ok := a.([]interface{})
		if !ok {
			return false
		}
		for _, bv := range bt {
			found := false
			for _, av := range aa {
				if jqContains(av, bv) {
					found = true
					break
				}
			}
			if !found {
				return false
			}
		}
		return true
	case string:
		as, ok := a.(string)
		return ok && strings.Contains(as, bt)
	default:
		return jqCompare(a, b) == 0
	}
}

// jqToJSONValue converts jq values back to plain JSON values (json.Number).
func jqToJSONValue(v interface{}) interface{} {
	switch t := v.(type) {
	case jqNumber:
		return json.Number(string(t))
	case []interface{}:
		out := make([]interface{}, len(t))
		for i, e := range t {
			out[i] = jqToJSONValue(e)
		}
		return out
	case map[string]interface{}:
		out := make(map[string]interface{}, len(t))
		for k, e := range t {
			out[k] = jqToJSONValue(e)
		}
		return out
	}
	return v
}
