// A small jq-like query language implementation.

// jqQuery is a compiled query.
type jqQuery interface {
	Run(input interface{}) ([]interface{}, error)
}

type jqProgram struct {
	root jqNode
	src  string
}

func (p *jqProgram) Run(input interface{}) ([]interface{}, error) {
	env := &jqEnv{}
	return p.root.eval(normalizeJSON(input), env)
}

// normalizeJSON converts json.Number into float64 for arithmetic while keeping
// the original representation when converting back.
func normalizeJSON(v interface{}) interface{} {
	switch t := v.(type) {
	case json.Number:
		return jqNumber(t)
	case []interface{}:
		out := make([]interface{}, len(t))
		for i, e := range t {
			out[i] = normalizeJSON(e)
		}
		return out
	case map[string]interface{}:
		out := make(map[string]interface{}, len(t))
		for k, e := range t {
			out[k] = normalizeJSON(e)
		}
		return out
	}
	return v
}

// jqNumber keeps number text.
type jqNumber string

func (n jqNumber) String() string { return string(n) }

// MarshalJSON outputs the number text.
func (n jqNumber) MarshalJSON() ([]byte, error) {
	if string(n) == "" {
		return []byte("0"), nil
	}
	return []byte(string(n)), nil
}

func toFloat(v interface{}) (float64, bool) {
	switch t := v.(type) {
	case jqNumber:
		f, err := strconv.ParseFloat(string(t), 64)
		if err != nil {
			return 0, false
		}
		return f, true
	case float64:
		return t, true
	case int:
		return float64(t), true
	case int64:
		return float64(t), true
	}
	return 0, false
}

func numberValue(f float64) interface{} {
	if math.IsInf(f, 0) || math.IsNaN(f) {
		return nil
	}
	if f == math.Trunc(f) && math.Abs(f) < 1e17 {
		return jqNumber(strconv.FormatInt(int64(f), 10))
	}
	return jqNumber(strconv.FormatFloat(f, 'g', -1, 64))
}

type jqEnv struct {
	vars map[string]interface{}
}

func (e *jqEnv) with(name string, v interface{}) *jqEnv {
	n := &jqEnv{vars: map[string]interface{}{}}
	for k, val := range e.vars {
		n.vars[k] = val
	}
	n.vars[name] = v
	return n
}

type jqNode interface {
	eval(in interface{}, env *jqEnv) ([]interface{}, error)
