// ---- lexer ----

type jqTokenKind int

const (
	tkEOF jqTokenKind = iota
	tkIdent
	tkField // .foo
	tkDot
	tkDotDot
	tkNumber
	tkString
	tkVar
	tkOp
	tkLParen
	tkRParen
	tkLBracket
	tkRBracket
	tkLBrace
	tkRBrace
	tkComma
	tkPipe
	tkColon
	tkQuestion
	tkKeyword
