			case []interface{}:
				out := make([]interface{}, len(t))
				for i, v := range t {
					out[len(t)-1-i] = v
				}
				return []interface{}{out}, nil
			case string:
				rs := []rune(t)
				for i, j := 0, len(rs)-1; i < j; i, j = i+1, j-1 {
					rs[i], rs[j] = rs[j], rs[i]
